/**
 * Beads CLI Bridge
 *
 * Provides a secure wrapper around the `bd` (Beads) CLI tool.
 * Implements command execution with proper input sanitization,
 * argument validation, JSONL parsing, and error handling.
 *
 * Security Features:
 * - All inputs validated with Zod schemas
 * - No shell execution (uses execFile)
 * - Command allowlist enforcement
 * - Argument sanitization
 * - JSONL streaming support
 *
 * @module v3/plugins/gastown-bridge/bridges/bd-bridge
 */

import { execFile, spawn, ChildProcess } from 'child_process';
import { promisify } from 'util';
import { z } from 'zod';

import {
  LRUCache,
  BatchDeduplicator,
  Lazy,
} from '../cache.js';

const execFileAsync = promisify(execFile);

// ============================================================================
// Performance Caches
// ============================================================================

/** Result cache for memoizing bead queries */
const beadQueryCache = new LRUCache<string, Bead[]>({
  maxEntries: 100,
  ttlMs: 30 * 1000, // 30 sec TTL (beads may change)
});

/** Single bead cache */
const singleBeadCache = new LRUCache<string, Bead>({
  maxEntries: 500,
  ttlMs: 60 * 1000, // 1 min TTL
});

/** Static data cache (version, stats) */
const staticCache = new LRUCache<string, unknown>({
  maxEntries: 50,
  ttlMs: 5 * 60 * 1000, // 5 min TTL
});

/** Deduplicator for concurrent CLI calls */
const execDedup = new BatchDeduplicator<BdResult<string>>();

/** Parsed JSONL cache */
const parsedCache = new LRUCache<string, Bead[]>({
  maxEntries: 100,
  ttlMs: 30 * 1000,
});

/**
 * FNV-1a hash for cache keys
 */
function hashArgs(args: string[]): string {
  let hash = 2166136261;
  for (const arg of args) {
    for (let i = 0; i < arg.length; i++) {
      hash ^= arg.charCodeAt(i);
      hash = (hash * 16777619) >>> 0;
    }
    hash ^= 0xff; // separator
  }
  return hash.toString(36);
}

// ============================================================================
// Zod Validation Schemas
// ============================================================================

/**
 * Safe string pattern - no shell metacharacters
 */
const SafeStringSchema = z.string()
  .max(4096, 'String too long')
  .refine(
    (val) => !/[;&|`$(){}><\n\r\0]/.test(val),
    'String contains shell metacharacters'
  );

/**
 * Safe identifier pattern
 */
const IdentifierSchema = z.string()
  .min(1, 'Identifier cannot be empty')
  .max(128, 'Identifier too long')
  .regex(/^[a-zA-Z][a-zA-Z0-9_-]*$/, 'Invalid identifier format');

/**
 * Bead ID schema (UUID or custom format)
 */
const BeadIdSchema = z.string()
  .min(1, 'Bead ID cannot be empty')
  .max(64, 'Bead ID too long')
  .regex(/^[a-zA-Z0-9_-]+$/, 'Invalid bead ID format');

/**
 * Bead type schema
 */
const BeadTypeSchema = z.enum([
  'prompt',
  'response',
  'code',
  'context',
  'memory',
  'tool-call',
  'tool-result',
  'system',
  'error',
  'metadata',
]);

/**
 * Bead schema
 */
export const BeadSchema = z.object({
  id: BeadIdSchema,
  type: BeadTypeSchema,
  content: z.string(),
  timestamp: z.string().datetime().optional(),
  metadata: z.record(z.unknown()).optional(),
  parentId: BeadIdSchema.optional(),
  threadId: z.string().optional(),
  agentId: z.string().optional(),
  tags: z.array(z.string()).optional(),
  embedding: z.array(z.number()).optional(),
  hash: z.string().optional(),
});

/**
 * BD command argument schema
 */
const BdArgumentSchema = z.string()
  .max(1024, 'Argument too long')
  .refine(
    (val) => !val.includes('\0'),
    'Argument contains null byte'
  )
  .refine(
    (val) => !/[;&|`$(){}><]/.test(val),
    'Argument contains shell metacharacters'
  );

// ============================================================================
// Types
// ============================================================================

/**
 * Bead type (inferred from schema)
 */
export type Bead = z.infer<typeof BeadSchema>;

/**
 * Bead type enum
 */
export type BeadType = z.infer<typeof BeadTypeSchema>;

/**
 * Beads bridge configuration
 */
export interface BdBridgeConfig {
  /**
   * Path to bd executable
   * Default: 'bd' (assumes in PATH)
   */
  bdPath?: string;

  /**
   * Working directory for execution
   */
  cwd?: string;

  /**
   * Execution timeout in milliseconds
   * Default: 60000 (60 seconds)
   */
  timeout?: number;

  /**
   * Maximum buffer size for output
   * Default: 50MB (beads can be large)
   */
  maxBuffer?: number;

  /**
   * Environment variables
   */
  env?: NodeJS.ProcessEnv;

  /**
   * Default storage path
   */
  storagePath?: string;
}

/**
 * Bead query parameters
 */
export interface BeadQuery {
  type?: BeadType | BeadType[];
  threadId?: string;
  agentId?: string;
  tags?: string[];
  after?: string; // ISO timestamp
  before?: string; // ISO timestamp
  limit?: number;
  offset?: number;
  sortBy?: 'timestamp' | 'id' | 'type';
  sortOrder?: 'asc' | 'desc';
}

/**
 * Bead creation parameters
 */
export interface CreateBeadParams {
  type: BeadType;
  content: string;
  parentId?: string;
  threadId?: string;
  agentId?: string;
  tags?: string[];
  metadata?: Record<string, unknown>;
}

/**
 * BD execution result
 */
export interface BdResult<T = unknown> {
  success: boolean;
  data?: T;
  error?: string;
  command: string;
  args: string[];
  durationMs: number;
}

/**
 * Streaming execution result
 */
export interface BdStreamResult {
  process: ChildProcess;
  stdout: NodeJS.ReadableStream | null;
  stderr: NodeJS.ReadableStream | null;
  promise: Promise<BdResult<string>>;
}

/**
 * Logger interface
 */
export interface BdLogger {
  debug: (msg: string, meta?: Record<string, unknown>) => void;
  info: (msg: string, meta?: Record<string, unknown>) => void;
  warn: (msg: string, meta?: Record<string, unknown>) => void;
  error: (msg: string, meta?: Record<string, unknown>) => void;
}

// ============================================================================
// Errors
// ============================================================================

/**
 * Beads bridge error codes
 */
export type BdErrorCode =
  | 'COMMAND_NOT_FOUND'
  | 'EXECUTION_FAILED'
  | 'TIMEOUT'
  | 'INVALID_ARGUMENT'
  | 'INVALID_OUTPUT'
  | 'PARSE_ERROR'
  | 'VALIDATION_ERROR'
  | 'BEAD_NOT_FOUND';

/**
 * Beads bridge error
 */
export class BdBridgeError extends Error {
  constructor(
    message: string,
    public readonly code: BdErrorCode,
    public readonly command?: string,
    public readonly args?: string[],
    public readonly cause?: Error
  ) {
    super(message);
    this.name = 'BdBridgeError';
  }
}

// ============================================================================
// Default Logger
// ============================================================================

const defaultLogger: BdLogger = {
  debug: (msg, meta) => console.debug(`[bd-bridge] ${msg}`, meta ?? ''),
  info: (msg, meta) => console.info(`[bd-bridge] ${msg}`, meta ?? ''),
  warn: (msg, meta) => console.warn(`[bd-bridge] ${msg}`, meta ?? ''),
  error: (msg, meta) => console.error(`[bd-bridge] ${msg}`, meta ?? ''),
};

// ============================================================================
// Allowed Commands
// ============================================================================

/**
 * Allowed bd subcommands (allowlist)
 */
const ALLOWED_BD_COMMANDS = new Set([
  'list',
  'get',
  'create',
  'update',
  'delete',
  'search',
  'export',
  'import',
  'thread',
  'stats',
  'help',
  'version',
  'config',
  'sync',
]);

// ============================================================================
// Beads Bridge Implementation
// ============================================================================

/**
 * Beads CLI Bridge
 *
 * Secure wrapper around the `bd` CLI tool for bead management.
 * Supports JSONL output parsing for streaming large datasets.
 *
 * @example
 * ```typescript
 * const bdBridge = new BdBridge({ bdPath: '/usr/local/bin/bd' });
 * await bdBridge.initialize();
 *
 * const beads = await bdBridge.listBeads({ type: 'prompt', limit: 100 });
 * ```
 */
export class BdBridge {
  private config: Required<BdBridgeConfig>;
  private logger: BdLogger;
  private initialized = false;

  /** Commands that can be cached (read-only, no side effects) */
  private static readonly CACHEABLE_COMMANDS = new Set([
    'list',
    'get',
    'search',
    'stats',
    'version',
    'help',
    'config',
  ]);

  /** Commands that should use longer cache (static data) */
  private static readonly STATIC_COMMANDS = new Set([
    'version',
    'help',
    'stats',
    'config',
  ]);

  constructor(config?: BdBridgeConfig, logger?: BdLogger) {
    this.config = {
      bdPath: config?.bdPath ?? 'bd',
      cwd: config?.cwd ?? process.cwd(),
      timeout: config?.timeout ?? 60000,
      maxBuffer: config?.maxBuffer ?? 50 * 1024 * 1024,
      env: config?.env ?? process.env,
      storagePath: config?.storagePath ?? '',
    };
    this.logger = logger ?? defaultLogger;
  }

  /**
   * Initialize the bridge and verify bd is available
   */
  async initialize(): Promise<void> {
    try {
      const result = await this.execBd(['version']);
      if (!result.success) {
        throw new BdBridgeError(
          'Failed to verify bd installation',
          'COMMAND_NOT_FOUND',
          'bd',
          ['version']
        );
      }
      this.initialized = true;
      this.logger.info('Beads bridge initialized', {
        bdPath: this.config.bdPath,
        version: result.data,
      });
    } catch (error) {
      if (error instanceof BdBridgeError) throw error;
      throw new BdBridgeError(
        'Failed to initialize Beads bridge',
        'COMMAND_NOT_FOUND',
        'bd',
        ['version'],
        error as Error
      );
    }
  }

  /**
   * Execute a bd command with validated arguments
   *
   * @param args - Command arguments (validated and sanitized)
   * @returns Command output
   */
  async execBd(args: string[], skipCache = false): Promise<BdResult<string>> {
    const startTime = Date.now();

    // Validate all arguments
    const validatedArgs = this.validateAndSanitizeArgs(args);

    // Validate subcommand is allowed
    const subcommand = validatedArgs[0];
    if (subcommand && !ALLOWED_BD_COMMANDS.has(subcommand)) {
      throw new BdBridgeError(
        `Command not allowed: ${subcommand}`,
        'INVALID_ARGUMENT',
        'bd',
        validatedArgs
      );
    }

    // Check cache for cacheable commands
    const cacheKey = hashArgs(validatedArgs);
    const isCacheable = !skipCache && subcommand && BdBridge.CACHEABLE_COMMANDS.has(subcommand);
    const isStatic = subcommand && BdBridge.STATIC_COMMANDS.has(subcommand);

    if (isCacheable) {
      const cached = staticCache.get(cacheKey) as BdResult<string> | undefined;
      if (cached) {
        this.logger.debug('Cache hit for bd command', { command: subcommand });
        return {
          ...cached,
          durationMs: 0, // Cached result
        };
      }
    }

    // Use deduplication for concurrent identical calls
    return execDedup.dedupe(cacheKey, async () => {
      try {
        this.logger.debug('Executing bd command', {
          command: 'bd',
          args: validatedArgs,
        });

        const { stdout, stderr } = await execFileAsync(
          this.config.bdPath,
          validatedArgs,
          {
            cwd: this.config.cwd,
            env: this.config.env,
            timeout: this.config.timeout,
            maxBuffer: this.config.maxBuffer,
            shell: false, // CRITICAL: Never use shell
            windowsHide: true,
          }
        );

        const durationMs = Date.now() - startTime;

        if (stderr && stderr.trim()) {
          this.logger.warn('bd stderr output', { stderr });
        }

        const result: BdResult<string> = {
          success: true,
          data: stdout.trim(),
          command: 'bd',
          args: validatedArgs,
          durationMs,
        };

        // Cache successful results
        if (isCacheable && result.success) {
          staticCache.set(cacheKey, result);
        }

        return result;
      } catch (error: unknown) {
        const durationMs = Date.now() - startTime;
        const err = error as NodeJS.ErrnoException & {
          killed?: boolean;
          stdout?: string;
          stderr?: string;
        };

        if (err.killed) {
          throw new BdBridgeError(
            'Command execution timed out',
            'TIMEOUT',
            'bd',
            validatedArgs
          );
        }

        if (err.code === 'ENOENT') {
          throw new BdBridgeError(
            `bd executable not found at: ${this.config.bdPath}`,
            'COMMAND_NOT_FOUND',
            'bd',
            validatedArgs
          );
        }

        return {
          success: false,
          error: err.stderr || err.message,
          command: 'bd',
          args: validatedArgs,
          durationMs,
        };
      }
    });
  }

  /**
   * Execute bd command with streaming output
   */
  execBdStreaming(args: string[]): BdStreamResult {
    const startTime = Date.now();

    // Validate all arguments
    const validatedArgs = this.validateAndSanitizeArgs(args);

    // Validate subcommand is allowed
    const subcommand = validatedArgs[0];
    if (subcommand && !ALLOWED_BD_COMMANDS.has(subcommand)) {
      throw new BdBridgeError(
        `Command not allowed: ${subcommand}`,
        'INVALID_ARGUMENT',
        'bd',
        validatedArgs
      );
    }

    this.logger.debug('Executing bd command (streaming)', {
      command: 'bd',
      args: validatedArgs,
    });

    const childProcess = spawn(this.config.bdPath, validatedArgs, {
      cwd: this.config.cwd,
      env: this.config.env,
      timeout: this.config.timeout,
      shell: false, // CRITICAL: Never use shell
      windowsHide: true,
    });

    const promise = new Promise<BdResult<string>>((resolve, reject) => {
      let stdout = '';
      let stderr = '';

      childProcess.stdout?.on('data', (data: Buffer) => {
        stdout += data.toString();
      });

      childProcess.stderr?.on('data', (data: Buffer) => {
        stderr += data.toString();
      });

      childProcess.on('close', (code) => {
        const durationMs = Date.now() - startTime;
        if (code === 0) {
          resolve({
            success: true,
            data: stdout.trim(),
            command: 'bd',
            args: validatedArgs,
            durationMs,
          });
        } else {
          resolve({
            success: false,
            error: stderr || `Process exited with code ${code}`,
            command: 'bd',
            args: validatedArgs,
            durationMs,
          });
        }
      });

      childProcess.on('error', (error) => {
        reject(new BdBridgeError(
          error.message,
          'EXECUTION_FAILED',
          'bd',
          validatedArgs
        ));
      });
    });

    return {
      process: childProcess,
      stdout: childProcess.stdout,
      stderr: childProcess.stderr,
      promise,
    };
  }

  /**
   * Parse JSONL output from bd command into Bead array
   *
   * @param output - JSONL formatted output
   * @returns Array of parsed and validated beads
   */
  parseBdOutput(output: string): Bead[] {
    if (!output || output.trim() === '') {
      return [];
    }

    // Check parsed cache first
    const cacheKey = hashArgs([output]);
    const cached = parsedCache.get(cacheKey);
    if (cached) {
      return cached;
    }

    const lines = output.trim().split('\n');
    const beads: Bead[] = [];
    const errors: Array<{ line: number; error: string }> = [];

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]?.trim();
      if (!line) continue;

      try {
        const parsed = JSON.parse(line);
        const validated = BeadSchema.parse(parsed);
        beads.push(validated);

        // Also cache individual beads
        singleBeadCache.set(validated.id, validated);
      } catch (error) {
        errors.push({
          line: i + 1,
          error: error instanceof Error ? error.message : String(error),
        });
      }
    }

    if (errors.length > 0) {
      this.logger.warn('Some beads failed to parse', {
        totalLines: lines.length,
        parsed: beads.length,
        errors: errors.length,
        firstErrors: errors.slice(0, 3),
      });
    }

    // Cache the parsed result
    parsedCache.set(cacheKey, beads);

    return beads;
  }

  /**
   * Parse single bead from JSON output
   */
  parseSingleBead(output: string): Bead {
    if (!output || output.trim() === '') {
      throw new BdBridgeError(
        'Empty output from bd command',
        'INVALID_OUTPUT'
      );
    }

    try {
      const parsed = JSON.parse(output);
      return BeadSchema.parse(parsed);
    } catch (error) {
      throw new BdBridgeError(
        'Failed to parse bead output',
        'PARSE_ERROR',
        undefined,
        undefined,
        error as Error
      );
    }
  }

  /**
   * List beads with optional query parameters
   */
  async listBeads(query?: BeadQuery): Promise<Bead[]> {
    this.ensureInitialized();

    const args = ['list', '--format', 'jsonl'];

    if (query?.type) {
      const types = Array.isArray(query.type) ? query.type : [query.type];
      for (const type of types) {
        args.push('--type', type);
      }
    }

    if (query?.threadId) {
      args.push('--thread', SafeStringSchema.parse(query.threadId));
    }

    if (query?.agentId) {
      args.push('--agent', SafeStringSchema.parse(query.agentId));
    }

    if (query?.tags && query.tags.length > 0) {
      for (const tag of query.tags) {
        args.push('--tag', SafeStringSchema.parse(tag));
      }
    }

    if (query?.after) {
      args.push('--after', query.after);
    }

    if (query?.before) {
      args.push('--before', query.before);
    }

    if (query?.limit !== undefined) {
      args.push('--limit', String(Math.min(query.limit, 10000)));
    }

    if (query?.offset !== undefined) {
      args.push('--offset', String(query.offset));
    }

    if (query?.sortBy) {
      args.push('--sort', query.sortBy);
    }

    if (query?.sortOrder) {
      args.push('--order', query.sortOrder);
    }

    const result = await this.execBd(args);
    if (!result.success) {
      throw new BdBridgeError(
        result.error ?? 'Failed to list beads',
        'EXECUTION_FAILED',
        'bd',
        args
      );
    }

    return this.parseBdOutput(result.data ?? '');
  }

  /**
   * Get a single bead by ID
   */
  async getBead(beadId: string): Promise<Bead> {
    this.ensureInitialized();

    const validatedId = BeadIdSchema.parse(beadId);

    // Check single bead cache first
    const cached = singleBeadCache.get(validatedId);
    if (cached) {
      this.logger.debug('Bead cache hit', { beadId: validatedId });
      return cached;
    }

    const args = ['get', validatedId, '--format', 'json'];

    const result = await this.execBd(args);
    if (!result.success) {
      if (result.error?.includes('not found')) {
        throw new BdBridgeError(
          `Bead not found: ${beadId}`,
          'BEAD_NOT_FOUND',
          'bd',
          args
        );
      }
      throw new BdBridgeError(
        result.error ?? 'Failed to get bead',
        'EXECUTION_FAILED',
        'bd',
        args
      );
    }

    const bead = this.parseSingleBead(result.data ?? '');

    // Cache the result
    singleBeadCache.set(bead.id, bead);

    return bead;
  }

  /**
   * Create a new bead
   */
  async createBead(params: CreateBeadParams): Promise<Bead> {
    this.ensureInitialized();

    const args = [
      'create',
      '--type', params.type,
      '--content', SafeStringSchema.parse(params.content),
      '--format', 'json',
    ];

    if (params.parentId) {
      args.push('--parent', BeadIdSchema.parse(params.parentId));
    }

    if (params.threadId) {
      args.push('--thread', SafeStringSchema.parse(params.threadId));
    }

    if (params.agentId) {
      args.push('--agent', SafeStringSchema.parse(params.agentId));
    }

    if (params.tags && params.tags.length > 0) {
      for (const tag of params.tags) {
        args.push('--tag', SafeStringSchema.parse(tag));
      }
    }

    if (params.metadata) {
      args.push('--metadata', JSON.stringify(params.metadata));
    }

    const result = await this.execBd(args);
    if (!result.success) {
      throw new BdBridgeError(
        result.error ?? 'Failed to create bead',
        'EXECUTION_FAILED',
        'bd',
        args
      );
    }

    return this.parseSingleBead(result.data ?? '');
  }

  /**
   * Search beads with semantic query
   */
  async searchBeads(query: string, options?: {
    limit?: number;
    threshold?: number;
    type?: BeadType | BeadType[];
  }): Promise<Bead[]> {
    this.ensureInitialized();

    const args = [
      'search',
      SafeStringSchema.parse(query),
      '--format', 'jsonl',
    ];

    if (options?.limit !== undefined) {
      args.push('--limit', String(Math.min(options.limit, 1000)));
    }

    if (options?.threshold !== undefined) {
      args.push('--threshold', String(options.threshold));
    }

    if (options?.type) {
      const types = Array.isArray(options.type) ? options.type : [options.type];
      for (const type of types) {
        args.push('--type', type);
      }
    }

    const result = await this.execBd(args);
    if (!result.success) {
      throw new BdBridgeError(
        result.error ?? 'Bead search failed',
        'EXECUTION_FAILED',
        'bd',
        args
      );
    }

    return this.parseBdOutput(result.data ?? '');
  }

  /**
   * Export beads to JSONL format
   */
  async exportBeads(query?: BeadQuery): Promise<string> {
    this.ensureInitialized();

    const args = ['export', '--format', 'jsonl'];

    if (query?.threadId) {
      args.push('--thread', SafeStringSchema.parse(query.threadId));
    }

    if (query?.after) {
      args.push('--after', query.after);
    }

    if (query?.before) {
      args.push('--before', query.before);
    }

    const result = await this.execBd(args);
    if (!result.success) {
      throw new BdBridgeError(
        result.error ?? 'Export failed',
        'EXECUTION_FAILED',
        'bd',
        args
      );
    }

    return result.data ?? '';
  }

  /**
   * Get bead statistics
   */
  async getStats(): Promise<{
    totalBeads: number;
    beadsByType: Record<string, number>;
    totalThreads: number;
    oldestBead?: string;
    newestBead?: string;
    storageSize?: number;
  }> {
    this.ensureInitialized();

    const args = ['stats', '--format', 'json'];

    const result = await this.execBd(args);
    if (!result.success) {
      throw new BdBridgeError(
        result.error ?? 'Failed to get stats',
        'EXECUTION_FAILED',
        'bd',
        args
      );
    }

    try {
      return JSON.parse(result.data ?? '{}');
    } catch {
      throw new BdBridgeError(
        'Failed to parse stats output',
        'PARSE_ERROR',
        'bd',
        args
      );
    }
  }

  /**
   * Validate and sanitize command arguments
   */
  private validateAndSanitizeArgs(args: string[]): string[] {
    return args.map((arg, index) => {
      try {
        return BdArgumentSchema.parse(arg);
      } catch (error) {
        throw new BdBridgeError(
          `Invalid argument at index ${index}: ${arg}`,
          'VALIDATION_ERROR',
          'bd',
          args,
          error as Error
        );
      }
    });
  }

  /**
   * Ensure bridge is initialized
   */
  private ensureInitialized(): void {
    if (!this.initialized) {
      throw new BdBridgeError(
        'Beads bridge not initialized. Call initialize() first.',
        'EXECUTION_FAILED'
      );
    }
  }

  /**
   * Check if bridge is initialized
   */
  isInitialized(): boolean {
    return this.initialized;
  }

  /**
   * Get current configuration
   */
  getConfig(): Readonly<Required<BdBridgeConfig>> {
    return { ...this.config };
  }

  /**
   * Get cache statistics for performance monitoring
   */
  getCacheStats(): {
    beadQueryCache: { entries: number; sizeBytes: number };
    singleBeadCache: { entries: number; sizeBytes: number };
    staticCache: { entries: number; sizeBytes: number };
    parsedCache: { entries: number; sizeBytes: number };
  } {
    return {
      beadQueryCache: beadQueryCache.stats(),
      singleBeadCache: singleBeadCache.stats(),
      staticCache: staticCache.stats(),
      parsedCache: parsedCache.stats(),
    };
  }

  /**
   * Clear all caches (useful for testing or memory pressure)
   */
  clearCaches(): void {
    beadQueryCache.clear();
    singleBeadCache.clear();
    staticCache.clear();
    parsedCache.clear();
  }

  /**
   * Invalidate cache for a specific bead (after create/update/delete)
   */
  invalidateBeadCache(beadId: string): void {
    singleBeadCache.delete(beadId);
    // Also clear query caches since they may contain stale data
    beadQueryCache.clear();
    parsedCache.clear();
  }
}

/**
 * Create a new Beads bridge instance
 */
export function createBdBridge(config?: BdBridgeConfig, logger?: BdLogger): BdBridge {
  return new BdBridge(config, logger);
}

// Export schemas for external use
export {
  SafeStringSchema,
  IdentifierSchema,
  BeadIdSchema,
  BeadTypeSchema,
  BdArgumentSchema,
};

export default BdBridge;

/**
 * Gas Town CLI Bridge
 *
 * Provides a secure wrapper around the `gt` (Gas Town) CLI tool.
 * Implements command execution with proper input sanitization,
 * argument validation, and error handling.
 *
 * Security Features:
 * - All inputs validated with Zod schemas
 * - No shell execution (uses execFile)
 * - Command allowlist enforcement
 * - Argument sanitization
 *
 * @module v3/plugins/gastown-bridge/bridges/gt-bridge
 */

import { execFile } from 'child_process';
import { promisify } from 'util';
import { z } from 'zod';

import {
  LRUCache,
  BatchDeduplicator,
  Lazy,
} from '../cache.js';

const execFileAsync = promisify(execFile);

// ============================================================================
// Performance Caches
// ============================================================================

/** Result cache for memoizing expensive CLI calls */
const resultCache = new LRUCache<string, GtResult<string>>({
  maxEntries: 200,
  ttlMs: 30 * 1000, // 30 sec TTL (gas prices change frequently)
});

/** Longer cache for static data like tx status */
const staticCache = new LRUCache<string, unknown>({
  maxEntries: 500,
  ttlMs: 5 * 60 * 1000, // 5 min TTL
});

/** Deduplicator for concurrent identical CLI calls */
const execDedup = new BatchDeduplicator<GtResult<string>>();

/** Lazy parsed output cache */
const parsedCache = new LRUCache<string, unknown>({
  maxEntries: 500,
  ttlMs: 60 * 1000, // 1 min TTL
});

/**
 * FNV-1a hash for cache keys
 */
function hashArgs(args: string[]): string {
  let hash = 2166136261;
  for (const arg of args) {
    for (let i = 0; i < arg.length; i++) {
      hash ^= arg.charCodeAt(i);
      hash = (hash * 16777619) >>> 0;
    }
    hash ^= 0xff; // separator
  }
  return hash.toString(36);
}

// ============================================================================
// Zod Validation Schemas
// ============================================================================

/**
 * Safe string pattern - no shell metacharacters
 */
const SafeStringSchema = z.string()
  .max(1024, 'String too long')
  .refine(
    (val) => !/[;&|`$(){}><\n\r\0]/.test(val),
    'String contains shell metacharacters'
  );

/**
 * Safe identifier pattern - alphanumeric with underscore/hyphen
 */
const IdentifierSchema = z.string()
  .min(1, 'Identifier cannot be empty')
  .max(64, 'Identifier too long')
  .regex(/^[a-zA-Z][a-zA-Z0-9_-]*$/, 'Invalid identifier format');

/**
 * Gas price schema
 */
const GasPriceSchema = z.number()
  .positive('Gas price must be positive')
  .max(1_000_000, 'Gas price exceeds maximum');

/**
 * Gas limit schema
 */
const GasLimitSchema = z.number()
  .int('Gas limit must be an integer')
  .positive('Gas limit must be positive')
  .max(30_000_000, 'Gas limit exceeds maximum');

/**
 * Transaction hash schema (0x prefixed hex)
 */
const TxHashSchema = z.string()
  .regex(/^0x[a-fA-F0-9]{64}$/, 'Invalid transaction hash format');

/**
 * Address schema (0x prefixed hex)
 */
const AddressSchema = z.string()
  .regex(/^0x[a-fA-F0-9]{40}$/, 'Invalid address format');

/**
 * Network schema
 */
const NetworkSchema = z.enum([
  'mainnet',
  'goerli',
  'sepolia',
  'polygon',
  'arbitrum',
  'optimism',
  'base',
  'local',
]);

/**
 * GT command argument schema
 */
const GtArgumentSchema = z.string()
  .max(512, 'Argument too long')
  .refine(
    (val) => !val.includes('\0'),
    'Argument contains null byte'
  )
  .refine(
    (val) => !/[;&|`$(){}><]/.test(val),
    'Argument contains shell metacharacters'
  );

// ============================================================================
// Types
// ============================================================================

/**
 * Gas Town executor configuration
 */
export interface GtBridgeConfig {
  /**
   * Path to gt executable
   * Default: 'gt' (assumes in PATH)
   */
  gtPath?: string;

  /**
   * Working directory for execution
   */
  cwd?: string;

  /**
   * Execution timeout in milliseconds
   * Default: 30000 (30 seconds)
   */
  timeout?: number;

  /**
   * Maximum buffer size for output
   * Default: 10MB
   */
  maxBuffer?: number;

  /**
   * Environment variables
   */
  env?: NodeJS.ProcessEnv;

  /**
   * Default network
   */
  defaultNetwork?: z.infer<typeof NetworkSchema>;
}

/**
 * Gas estimation result
 */
export interface GasEstimate {
  gasLimit: number;
  gasPrice: string;
  maxFeePerGas?: string;
  maxPriorityFeePerGas?: string;
  estimatedCost: string;
  estimatedCostUsd?: number;
}

/**
 * Transaction status
 */
export interface TxStatus {
  hash: string;
  status: 'pending' | 'confirmed' | 'failed' | 'dropped';
  blockNumber?: number;
  confirmations?: number;
  gasUsed?: number;
  effectiveGasPrice?: string;
  error?: string;
}

/**
 * Network status
 */
export interface NetworkStatus {
  network: string;
  chainId: number;
  blockNumber: number;
  baseFee?: string;
  gasPrice?: string;
  connected: boolean;
}

/**
 * GT execution result
 */
export interface GtResult<T = unknown> {
  success: boolean;
  data?: T;
  error?: string;
  command: string;
  args: string[];
  durationMs: number;
}

/**
 * Logger interface
 */
export interface GtLogger {
  debug: (msg: string, meta?: Record<string, unknown>) => void;
  info: (msg: string, meta?: Record<string, unknown>) => void;
  warn: (msg: string, meta?: Record<string, unknown>) => void;
  error: (msg: string, meta?: Record<string, unknown>) => void;
}

// ============================================================================
// Errors
// ============================================================================

/**
 * Gas Town bridge error codes
 */
export type GtErrorCode =
  | 'COMMAND_NOT_FOUND'
  | 'EXECUTION_FAILED'
  | 'TIMEOUT'
  | 'INVALID_ARGUMENT'
  | 'INVALID_OUTPUT'
  | 'NETWORK_ERROR'
  | 'VALIDATION_ERROR';

/**
 * Gas Town bridge error
 */
export class GtBridgeError extends Error {
  constructor(
    message: string,
    public readonly code: GtErrorCode,
    public readonly command?: string,
    public readonly args?: string[],
    public readonly cause?: Error
  ) {
    super(message);
    this.name = 'GtBridgeError';
  }
}

// ============================================================================
// Default Logger
// ============================================================================

const defaultLogger: GtLogger = {
  debug: (msg, meta) => console.debug(`[gt-bridge] ${msg}`, meta ?? ''),
  info: (msg, meta) => console.info(`[gt-bridge] ${msg}`, meta ?? ''),
  warn: (msg, meta) => console.warn(`[gt-bridge] ${msg}`, meta ?? ''),
  error: (msg, meta) => console.error(`[gt-bridge] ${msg}`, meta ?? ''),
};

// ============================================================================
// Allowed Commands
// ============================================================================

/**
 * Allowed gt subcommands (allowlist)
 */
const ALLOWED_GT_COMMANDS = new Set([
  'estimate',
  'status',
  'network',
  'price',
  'tx',
  'simulate',
  'decode',
  'encode',
  'help',
  'version',
  'config',
]);

// ============================================================================
// Gas Town Bridge Implementation
// ============================================================================

/**
 * Gas Town CLI Bridge
 *
 * Secure wrapper around the `gt` CLI tool for gas estimation
 * and transaction management.
 *
 * @example
 * ```typescript
 * const gtBridge = new GtBridge({ gtPath: '/usr/local/bin/gt' });
 * await gtBridge.initialize();
 *
 * const estimate = await gtBridge.estimateGas({
 *   to: '0x...',
 *   data: '0x...',
 *   network: 'mainnet',
 * });
 * ```
 */
export class GtBridge {
  private config: Required<GtBridgeConfig>;
  private logger: GtLogger;
  private initialized = false;

  /** Commands that can be cached (read-only, no side effects) */
  private static readonly CACHEABLE_COMMANDS = new Set([
    'version',
    'status',
    'price',
    'decode',
    'help',
    'config',
  ]);

  /** Commands that should use longer cache (static data) */
  private static readonly STATIC_COMMANDS = new Set([
    'version',
    'help',
    'decode',
  ]);

  constructor(config?: GtBridgeConfig, logger?: GtLogger) {
    this.config = {
      gtPath: config?.gtPath ?? 'gt',
      cwd: config?.cwd ?? process.cwd(),
      timeout: config?.timeout ?? 30000,
      maxBuffer: config?.maxBuffer ?? 10 * 1024 * 1024,
      env: config?.env ?? process.env,
      defaultNetwork: config?.defaultNetwork ?? 'mainnet',
    };
    this.logger = logger ?? defaultLogger;
  }

  /**
   * Initialize the bridge and verify gt is available
   */
  async initialize(): Promise<void> {
    try {
      const result = await this.execGt(['version']);
      if (!result.success) {
        throw new GtBridgeError(
          'Failed to verify gt installation',
          'COMMAND_NOT_FOUND',
          'gt',
          ['version']
        );
      }
      this.initialized = true;
      this.logger.info('Gas Town bridge initialized', {
        gtPath: this.config.gtPath,
        version: result.data,
      });
    } catch (error) {
      if (error instanceof GtBridgeError) throw error;
      throw new GtBridgeError(
        'Failed to initialize Gas Town bridge',
        'COMMAND_NOT_FOUND',
        'gt',
        ['version'],
        error as Error
      );
    }
  }

  /**
   * Execute a gt command with validated arguments
   *
   * @param args - Command arguments (validated and sanitized)
   * @returns Command output
   */
  async execGt(args: string[], skipCache = false): Promise<GtResult<string>> {
    const startTime = Date.now();

    // Validate all arguments
    const validatedArgs = this.validateAndSanitizeArgs(args);

    // Validate subcommand is allowed
    const subcommand = validatedArgs[0];
    if (subcommand && !ALLOWED_GT_COMMANDS.has(subcommand)) {
      throw new GtBridgeError(
        `Command not allowed: ${subcommand}`,
        'INVALID_ARGUMENT',
        'gt',
        validatedArgs
      );
    }

    // Check cache for cacheable commands
    const cacheKey = hashArgs(validatedArgs);
    const isCacheable = !skipCache && subcommand && GtBridge.CACHEABLE_COMMANDS.has(subcommand);
    const isStatic = subcommand && GtBridge.STATIC_COMMANDS.has(subcommand);

    if (isCacheable) {
      const cached = isStatic
        ? staticCache.get(cacheKey) as GtResult<string> | undefined
        : resultCache.get(cacheKey);
      if (cached) {
        this.logger.debug('Cache hit for gt command', { command: subcommand });
        return {
          ...cached,
          durationMs: 0, // Cached result
        };
      }
    }

    // Use deduplication for concurrent identical calls
    return execDedup.dedupe(cacheKey, async () => {
      try {
        this.logger.debug('Executing gt command', {
          command: 'gt',
          args: validatedArgs,
        });

        const { stdout, stderr } = await execFileAsync(
          this.config.gtPath,
          validatedArgs,
          {
            cwd: this.config.cwd,
            env: this.config.env,
            timeout: this.config.timeout,
            maxBuffer: this.config.maxBuffer,
            shell: false, // CRITICAL: Never use shell
            windowsHide: true,
          }
        );

        const durationMs = Date.now() - startTime;

        if (stderr && stderr.trim()) {
          this.logger.warn('gt stderr output', { stderr });
        }

        const result: GtResult<string> = {
          success: true,
          data: stdout.trim(),
          command: 'gt',
          args: validatedArgs,
          durationMs,
        };

        // Cache successful results
        if (isCacheable && result.success) {
          if (isStatic) {
            staticCache.set(cacheKey, result);
          } else {
            resultCache.set(cacheKey, result);
          }
        }

        return result;
      } catch (error: unknown) {
        const durationMs = Date.now() - startTime;
        const err = error as NodeJS.ErrnoException & {
          killed?: boolean;
          stdout?: string;
          stderr?: string;
        };

        if (err.killed) {
          throw new GtBridgeError(
            'Command execution timed out',
            'TIMEOUT',
            'gt',
            validatedArgs
          );
        }

        if (err.code === 'ENOENT') {
          throw new GtBridgeError(
            `gt executable not found at: ${this.config.gtPath}`,
            'COMMAND_NOT_FOUND',
            'gt',
            validatedArgs
          );
        }

        return {
          success: false,
          error: err.stderr || err.message,
          command: 'gt',
          args: validatedArgs,
          durationMs,
        };
      }
    });
  }

  /**
   * Parse JSON output from gt command
   *
   * @param output - Raw command output
   * @returns Parsed JSON object
   */
  parseGtOutput<T>(output: string): T {
    if (!output || output.trim() === '') {
      throw new GtBridgeError(
        'Empty output from gt command',
        'INVALID_OUTPUT'
      );
    }

    // Check parsed cache first
    const cacheKey = hashArgs([output]);
    const cached = parsedCache.get(cacheKey);
    if (cached !== undefined) {
      return cached as T;
    }

    try {
      // Try to parse as JSON
      const parsed = JSON.parse(output) as T;
      parsedCache.set(cacheKey, parsed);
      return parsed;
    } catch {
      // If not JSON, try to extract JSON from output
      const jsonMatch = output.match(/\{[\s\S]*\}|\[[\s\S]*\]/);
      if (jsonMatch) {
        try {
          const parsed = JSON.parse(jsonMatch[0]) as T;
          parsedCache.set(cacheKey, parsed);
          return parsed;
        } catch {
          throw new GtBridgeError(
            'Failed to parse gt output as JSON',
            'INVALID_OUTPUT'
          );
        }
      }

      throw new GtBridgeError(
        'Output is not valid JSON',
        'INVALID_OUTPUT'
      );
    }
  }

  /**
   * Estimate gas for a transaction
   */
  async estimateGas(params: {
    to: string;
    data?: string;
    value?: string;
    from?: string;
    network?: z.infer<typeof NetworkSchema>;
  }): Promise<GasEstimate> {
    this.ensureInitialized();

    // Validate parameters
    const validatedTo = AddressSchema.parse(params.to);
    const network = params.network ?? this.config.defaultNetwork;

    const args = ['estimate', '--to', validatedTo, '--network', network, '--json'];

    if (params.data) {
      const validatedData = SafeStringSchema.parse(params.data);
      args.push('--data', validatedData);
    }

    if (params.value) {
      const validatedValue = SafeStringSchema.parse(params.value);
      args.push('--value', validatedValue);
    }

    if (params.from) {
      const validatedFrom = AddressSchema.parse(params.from);
      args.push('--from', validatedFrom);
    }

    const result = await this.execGt(args);
    if (!result.success || !result.data) {
      throw new GtBridgeError(
        result.error ?? 'Gas estimation failed',
        'EXECUTION_FAILED',
        'gt',
        args
      );
    }

    return this.parseGtOutput<GasEstimate>(result.data);
  }

  /**
   * Get transaction status
   */
  async getTxStatus(txHash: string, network?: z.infer<typeof NetworkSchema>): Promise<TxStatus> {
    this.ensureInitialized();

    const validatedHash = TxHashSchema.parse(txHash);
    const args = [
      'tx',
      'status',
      validatedHash,
      '--network',
      network ?? this.config.defaultNetwork,
      '--json',
    ];

    const result = await this.execGt(args);
    if (!result.success || !result.data) {
      throw new GtBridgeError(
        result.error ?? 'Failed to get transaction status',
        'EXECUTION_FAILED',
        'gt',
        args
      );
    }

    return this.parseGtOutput<TxStatus>(result.data);
  }

  /**
   * Get network status
   */
  async getNetworkStatus(network?: z.infer<typeof NetworkSchema>): Promise<NetworkStatus> {
    this.ensureInitialized();

    const args = [
      'network',
      'status',
      '--network',
      network ?? this.config.defaultNetwork,
      '--json',
    ];

    const result = await this.execGt(args);
    if (!result.success || !result.data) {
      throw new GtBridgeError(
        result.error ?? 'Failed to get network status',
        'NETWORK_ERROR',
        'gt',
        args
      );
    }

    return this.parseGtOutput<NetworkStatus>(result.data);
  }

  /**
   * Get current gas price
   */
  async getGasPrice(network?: z.infer<typeof NetworkSchema>): Promise<{
    gasPrice: string;
    maxFeePerGas?: string;
    maxPriorityFeePerGas?: string;
    baseFee?: string;
  }> {
    this.ensureInitialized();

    const args = [
      'price',
      '--network',
      network ?? this.config.defaultNetwork,
      '--json',
    ];

    const result = await this.execGt(args);
    if (!result.success || !result.data) {
      throw new GtBridgeError(
        result.error ?? 'Failed to get gas price',
        'EXECUTION_FAILED',
        'gt',
        args
      );
    }

    return this.parseGtOutput(result.data);
  }

  /**
   * Simulate a transaction
   */
  async simulate(params: {
    to: string;
    data: string;
    value?: string;
    from?: string;
    network?: z.infer<typeof NetworkSchema>;
    blockNumber?: number;
  }): Promise<{
    success: boolean;
    returnData?: string;
    gasUsed?: number;
    logs?: unknown[];
    error?: string;
  }> {
    this.ensureInitialized();

    const validatedTo = AddressSchema.parse(params.to);
    const validatedData = SafeStringSchema.parse(params.data);
    const network = params.network ?? this.config.defaultNetwork;

    const args = [
      'simulate',
      '--to', validatedTo,
      '--data', validatedData,
      '--network', network,
      '--json',
    ];

    if (params.value) {
      args.push('--value', SafeStringSchema.parse(params.value));
    }

    if (params.from) {
      args.push('--from', AddressSchema.parse(params.from));
    }

    if (params.blockNumber !== undefined) {
      args.push('--block', String(params.blockNumber));
    }

    const result = await this.execGt(args);
    if (!result.success || !result.data) {
      throw new GtBridgeError(
        result.error ?? 'Transaction simulation failed',
        'EXECUTION_FAILED',
        'gt',
        args
      );
    }

    return this.parseGtOutput(result.data);
  }

  /**
   * Decode transaction data
   */
  async decode(data: string, abi?: string): Promise<{
    method: string;
    args: unknown[];
    signature: string;
  }> {
    this.ensureInitialized();

    const validatedData = SafeStringSchema.parse(data);
    const args = ['decode', validatedData, '--json'];

    if (abi) {
      const validatedAbi = SafeStringSchema.parse(abi);
      args.push('--abi', validatedAbi);
    }

    const result = await this.execGt(args);
    if (!result.success || !result.data) {
      throw new GtBridgeError(
        result.error ?? 'Failed to decode transaction data',
        'EXECUTION_FAILED',
        'gt',
        args
      );
    }

    return this.parseGtOutput(result.data);
  }

  /**
   * Validate and sanitize command arguments
   */
  private validateAndSanitizeArgs(args: string[]): string[] {
    return args.map((arg, index) => {
      try {
        return GtArgumentSchema.parse(arg);
      } catch (error) {
        throw new GtBridgeError(
          `Invalid argument at index ${index}: ${arg}`,
          'VALIDATION_ERROR',
          'gt',
          args,
          error as Error
        );
      }
    });
  }

  /**
   * Ensure bridge is initialized
   */
  private ensureInitialized(): void {
    if (!this.initialized) {
      throw new GtBridgeError(
        'Gas Town bridge not initialized. Call initialize() first.',
        'EXECUTION_FAILED'
      );
    }
  }

  /**
   * Check if bridge is initialized
   */
  isInitialized(): boolean {
    return this.initialized;
  }

  /**
   * Get current configuration
   */
  getConfig(): Readonly<Required<GtBridgeConfig>> {
    return { ...this.config };
  }

  /**
   * Get cache statistics for performance monitoring
   */
  getCacheStats(): {
    resultCache: { entries: number; sizeBytes: number };
    staticCache: { entries: number; sizeBytes: number };
    parsedCache: { entries: number; sizeBytes: number };
  } {
    return {
      resultCache: resultCache.stats(),
      staticCache: staticCache.stats(),
      parsedCache: parsedCache.stats(),
    };
  }

  /**
   * Clear all caches (useful for testing or memory pressure)
   */
  clearCaches(): void {
    resultCache.clear();
    staticCache.clear();
    parsedCache.clear();
  }
}

/**
 * Create a new Gas Town bridge instance
 */
export function createGtBridge(config?: GtBridgeConfig, logger?: GtLogger): GtBridge {
  return new GtBridge(config, logger);
}

// Export schemas for external use
export {
  SafeStringSchema,
  IdentifierSchema,
  GasPriceSchema,
  GasLimitSchema,
  TxHashSchema,
  AddressSchema,
  NetworkSchema,
  GtArgumentSchema,
};

export default GtBridge;

/**
 * Beads-AgentDB Sync Bridge
 *
 * Provides bidirectional synchronization between Beads (bd)
 * and AgentDB. Implements conflict resolution strategies
 * and maintains consistency between the two systems.
 *
 * Features:
 * - Bidirectional sync (Beads <-> AgentDB)
 * - Conflict resolution strategies
 * - Incremental sync support
 * - Transaction-safe operations
 * - Embedding preservation
 *
 * @module v3/plugins/gastown-bridge/bridges/sync-bridge
 */

import { z } from 'zod';
import { BdBridge, createBdBridge, type Bead, type BeadType, type BdBridgeConfig } from './bd-bridge.js';

import {
  LRUCache,
  BatchDeduplicator,
} from '../cache.js';

// ============================================================================
// Performance Caches
// ============================================================================

/** Cache for AgentDB lookups during sync */
const agentDBLookupCache = new LRUCache<string, AgentDBEntry | null>({
  maxEntries: 500,
  ttlMs: 30 * 1000, // 30 sec TTL
});

/** Cache for conflict detection results */
const conflictCache = new LRUCache<string, boolean>({
  maxEntries: 200,
  ttlMs: 10 * 1000, // 10 sec TTL
});

/** Deduplicator for concurrent sync operations */
const syncDedup = new BatchDeduplicator<SyncResult>();

/**
 * FNV-1a hash for cache keys
 */
function hashKey(parts: string[]): string {
  let hash = 2166136261;
  for (const part of parts) {
    for (let i = 0; i < part.length; i++) {
      hash ^= part.charCodeAt(i);
      hash = (hash * 16777619) >>> 0;
    }
    hash ^= 0xff;
  }
  return hash.toString(36);
}

// ============================================================================
// Zod Validation Schemas
// ============================================================================

/**
 * Sync conflict resolution strategy
 */
const ConflictStrategySchema = z.enum([
  'beads-wins',      // Beads data takes precedence
  'agentdb-wins',    // AgentDB data takes precedence
  'newest-wins',     // Most recent timestamp wins
  'merge',           // Attempt to merge fields
  'manual',          // Flag for manual resolution
]);

/**
 * Sync direction
 */
const SyncDirectionSchema = z.enum([
  'to-agentdb',      // Beads -> AgentDB
  'from-agentdb',    // AgentDB -> Beads
  'bidirectional',   // Both directions
]);

/**
 * Sync status
 */
const SyncStatusSchema = z.enum([
  'pending',
  'in-progress',
  'completed',
  'failed',
  'conflict',
]);

/**
 * AgentDB entry schema (compatible with claude-flow memory)
 */
const AgentDBEntrySchema = z.object({
  key: z.string(),
  value: z.unknown(),
  namespace: z.string().optional(),
  metadata: z.record(z.unknown()).optional(),
  embedding: z.array(z.number()).optional(),
  createdAt: z.string().datetime().optional(),
  updatedAt: z.string().datetime().optional(),
  version: z.number().optional(),
});

// ============================================================================
// Types
// ============================================================================

/**
 * Conflict resolution strategy type
 */
export type ConflictStrategy = z.infer<typeof ConflictStrategySchema>;

/**
 * Sync direction type
 */
export type SyncDirection = z.infer<typeof SyncDirectionSchema>;

/**
 * Sync status type
 */
export type SyncStatus = z.infer<typeof SyncStatusSchema>;

/**
 * AgentDB entry type
 */
export type AgentDBEntry = z.infer<typeof AgentDBEntrySchema>;

/**
 * Sync bridge configuration
 */
export interface SyncBridgeConfig {
  /**
   * Beads bridge configuration
   */
  beadsBridge?: BdBridgeConfig;

  /**
   * AgentDB namespace for beads
   * Default: 'beads'
   */
  agentdbNamespace?: string;

  /**
   * Conflict resolution strategy
   * Default: 'newest-wins'
   */
  conflictStrategy?: ConflictStrategy;

  /**
   * Batch size for sync operations
   * Default: 100
   */
  batchSize?: number;

  /**
   * Whether to preserve embeddings during sync
   * Default: true
   */
  preserveEmbeddings?: boolean;

  /**
   * Whether to sync metadata
   * Default: true
   */
  syncMetadata?: boolean;
}

/**
 * Sync operation result
 */
export interface SyncResult {
  success: boolean;
  direction: SyncDirection;
  synced: number;
  created: number;
  updated: number;
  deleted: number;
  conflicts: number;
  errors: Array<{ id: string; error: string }>;
  durationMs: number;
  timestamp: string;
}

/**
 * Conflict record
 */
export interface SyncConflict {
  beadId: string;
  beadData: Bead;
  agentdbData: AgentDBEntry;
  conflictType: 'update' | 'delete' | 'create';
  resolution?: 'beads' | 'agentdb' | 'merged' | 'pending';
  resolvedAt?: string;
}

/**
 * Sync state for incremental sync
 */
export interface SyncState {
  lastSyncTime: string;
  lastBeadId?: string;
  lastAgentDBKey?: string;
  pendingConflicts: string[];
  version: number;
}

/**
 * AgentDB interface (to be provided by claude-flow)
 */
export interface IAgentDBService {
  store(key: string, value: unknown, namespace?: string, metadata?: Record<string, unknown>): Promise<void>;
  retrieve(key: string, namespace?: string): Promise<AgentDBEntry | null>;
  search(query: string, namespace?: string, limit?: number): Promise<AgentDBEntry[]>;
  list(namespace?: string, limit?: number, offset?: number): Promise<AgentDBEntry[]>;
  delete(key: string, namespace?: string): Promise<void>;
  getNamespaceStats(namespace: string): Promise<{ count: number; lastUpdated?: string }>;
}

/**
 * Logger interface
 */
export interface SyncLogger {
  debug: (msg: string, meta?: Record<string, unknown>) => void;
  info: (msg: string, meta?: Record<string, unknown>) => void;
  warn: (msg: string, meta?: Record<string, unknown>) => void;
  error: (msg: string, meta?: Record<string, unknown>) => void;
}

// ============================================================================
// Errors
// ============================================================================

/**
 * Sync bridge error codes
 */
export type SyncErrorCode =
  | 'NOT_INITIALIZED'
  | 'SYNC_FAILED'
  | 'CONFLICT_UNRESOLVED'
  | 'AGENTDB_ERROR'
  | 'BEADS_ERROR'
  | 'VALIDATION_ERROR'
  | 'TRANSACTION_FAILED';

/**
 * Sync bridge error
 */
export class SyncBridgeError extends Error {
  constructor(
    message: string,
    public readonly code: SyncErrorCode,
    public readonly details?: Record<string, unknown>,
    public readonly cause?: Error
  ) {
    super(message);
    this.name = 'SyncBridgeError';
  }
}

// ============================================================================
// Default Logger
// ============================================================================

const defaultLogger: SyncLogger = {
  debug: (msg, meta) => console.debug(`[sync-bridge] ${msg}`, meta ?? ''),
  info: (msg, meta) => console.info(`[sync-bridge] ${msg}`, meta ?? ''),
  warn: (msg, meta) => console.warn(`[sync-bridge] ${msg}`, meta ?? ''),
  error: (msg, meta) => console.error(`[sync-bridge] ${msg}`, meta ?? ''),
};

// ============================================================================
// Sync Bridge Implementation
// ============================================================================

/**
 * Beads-AgentDB Sync Bridge
 *
 * Provides bidirectional synchronization between Beads and AgentDB
 * with configurable conflict resolution.
 *
 * @example
 * ```typescript
 * const syncBridge = new SyncBridge(agentDB, {
 *   conflictStrategy: 'newest-wins',
 *   agentdbNamespace: 'conversation-beads',
 * });
 * await syncBridge.initialize();
 *
 * // Sync beads to AgentDB
 * const result = await syncBridge.syncToAgentDB(beads);
 *
 * // Sync from AgentDB back to beads
 * const beads = await syncBridge.syncFromAgentDB();
 * ```
 */
export class SyncBridge {
  private bdBridge: BdBridge;
  private agentDB: IAgentDBService;
  private config: Required<SyncBridgeConfig>;
  private logger: SyncLogger;
  private initialized = false;
  private syncState: SyncState;
  private conflicts: Map<string, SyncConflict> = new Map();

  constructor(
    agentDB: IAgentDBService,
    config?: SyncBridgeConfig,
    logger?: SyncLogger
  ) {
    this.agentDB = agentDB;
    this.config = {
      beadsBridge: config?.beadsBridge ?? {},
      agentdbNamespace: config?.agentdbNamespace ?? 'beads',
      conflictStrategy: config?.conflictStrategy ?? 'newest-wins',
      batchSize: config?.batchSize ?? 100,
      preserveEmbeddings: config?.preserveEmbeddings ?? true,
      syncMetadata: config?.syncMetadata ?? true,
    };
    this.logger = logger ?? defaultLogger;
    this.bdBridge = createBdBridge(this.config.beadsBridge, {
      debug: (msg, meta) => this.logger.debug(`[bd] ${msg}`, meta),
      info: (msg, meta) => this.logger.info(`[bd] ${msg}`, meta),
      warn: (msg, meta) => this.logger.warn(`[bd] ${msg}`, meta),
      error: (msg, meta) => this.logger.error(`[bd] ${msg}`, meta),
    });
    this.syncState = {
      lastSyncTime: new Date(0).toISOString(),
      pendingConflicts: [],
      version: 1,
    };
  }

  /**
   * Initialize the sync bridge
   */
  async initialize(): Promise<void> {
    try {
      await this.bdBridge.initialize();

      // Load sync state from AgentDB if exists
      const savedState = await this.agentDB.retrieve(
        '_sync_state',
        this.config.agentdbNamespace
      );

      if (savedState?.value) {
        const parsed = savedState.value as SyncState;
        this.syncState = {
          lastSyncTime: parsed.lastSyncTime ?? new Date(0).toISOString(),
          lastBeadId: parsed.lastBeadId,
          lastAgentDBKey: parsed.lastAgentDBKey,
          pendingConflicts: parsed.pendingConflicts ?? [],
          version: (parsed.version ?? 0) + 1,
        };
      }

      this.initialized = true;
      this.logger.info('Sync bridge initialized', {
        namespace: this.config.agentdbNamespace,
        conflictStrategy: this.config.conflictStrategy,
        syncState: this.syncState,
      });
    } catch (error) {
      throw new SyncBridgeError(
        'Failed to initialize sync bridge',
        'NOT_INITIALIZED',
        undefined,
        error as Error
      );
    }
  }

  /**
   * Sync beads to AgentDB
   */
  async syncToAgentDB(beads: Bead[]): Promise<SyncResult> {
    this.ensureInitialized();

    const startTime = Date.now();
    const result: SyncResult = {
      success: true,
      direction: 'to-agentdb',
      synced: 0,
      created: 0,
      updated: 0,
      deleted: 0,
      conflicts: 0,
      errors: [],
      durationMs: 0,
      timestamp: new Date().toISOString(),
    };

    this.logger.info(`Starting sync to AgentDB: ${beads.length} beads`);

    // Process in batches with parallel lookups
    for (let i = 0; i < beads.length; i += this.config.batchSize) {
      const batch = beads.slice(i, i + this.config.batchSize);

      // Parallel lookup for all beads in batch
      const lookupPromises = batch.map(async (bead) => {
        const key = this.beadToKey(bead);
        const cacheKey = hashKey([key, this.config.agentdbNamespace]);

        // Check cache first
        if (agentDBLookupCache.has(cacheKey)) {
          return { bead, key, existing: agentDBLookupCache.get(cacheKey) };
        }

        const existing = await this.agentDB.retrieve(key, this.config.agentdbNamespace);
        agentDBLookupCache.set(cacheKey, existing);
        return { bead, key, existing };
      });

      const lookupResults = await Promise.all(lookupPromises);

      // Process results
      for (const { bead, key, existing } of lookupResults) {
        try {
          if (existing) {
            // Check for conflicts (use cache)
            const conflictCacheKey = hashKey([bead.id, bead.content, existing.key]);
            let hasConflict = conflictCache.get(conflictCacheKey);

            if (hasConflict === undefined) {
              hasConflict = await this.detectConflict(bead, existing);
              conflictCache.set(conflictCacheKey, hasConflict);
            }

            if (hasConflict) {
              const resolved = await this.resolveConflict(bead, existing);
              if (!resolved) {
                result.conflicts++;
                continue;
              }
            }
            result.updated++;
          } else {
            result.created++;
          }

          // Store bead in AgentDB
          await this.agentDB.store(
            key,
            this.beadToAgentDBValue(bead),
            this.config.agentdbNamespace,
            this.buildMetadata(bead)
          );

          // Invalidate lookup cache for this key
          const cacheKey = hashKey([key, this.config.agentdbNamespace]);
          agentDBLookupCache.delete(cacheKey);

          result.synced++;
        } catch (error) {
          result.errors.push({
            id: bead.id,
            error: error instanceof Error ? error.message : String(error),
          });
          this.logger.error(`Failed to sync bead ${bead.id}`, { error });
        }
      }
    }

    // Update sync state
    this.syncState.lastSyncTime = result.timestamp;
    if (beads.length > 0) {
      this.syncState.lastBeadId = beads[beads.length - 1]?.id;
    }
    await this.saveSyncState();

    result.durationMs = Date.now() - startTime;
    result.success = result.errors.length === 0 && result.conflicts === 0;

    this.logger.info('Sync to AgentDB complete', {
      synced: result.synced,
      created: result.created,
      updated: result.updated,
      conflicts: result.conflicts,
      errors: result.errors.length,
      durationMs: result.durationMs,
    });

    return result;
  }

  /**
   * Sync from AgentDB to Beads
   */
  async syncFromAgentDB(): Promise<Bead[]> {
    this.ensureInitialized();

    const startTime = Date.now();
    const beads: Bead[] = [];

    this.logger.info('Starting sync from AgentDB');

    try {
      // Get all entries from AgentDB namespace
      let offset = 0;
      let hasMore = true;

      while (hasMore) {
        const entries = await this.agentDB.list(
          this.config.agentdbNamespace,
          this.config.batchSize,
          offset
        );

        if (entries.length === 0) {
          hasMore = false;
          continue;
        }

        for (const entry of entries) {
          // Skip sync state entry
          if (entry.key === '_sync_state') continue;

          try {
            const bead = this.agentDBToBead(entry);
            if (bead) {
              beads.push(bead);
            }
          } catch (error) {
            this.logger.warn(`Failed to convert AgentDB entry to bead: ${entry.key}`, {
              error: error instanceof Error ? error.message : String(error),
            });
          }
        }

        offset += entries.length;
        hasMore = entries.length === this.config.batchSize;
      }

      // Update sync state
      this.syncState.lastSyncTime = new Date().toISOString();
      await this.saveSyncState();

      const durationMs = Date.now() - startTime;
      this.logger.info('Sync from AgentDB complete', {
        beads: beads.length,
        durationMs,
      });

      return beads;
    } catch (error) {
      throw new SyncBridgeError(
        'Failed to sync from AgentDB',
        'SYNC_FAILED',
        undefined,
        error as Error
      );
    }
  }

  /**
   * Perform full bidirectional sync
   */
  async syncBidirectional(): Promise<{
    toAgentDB: SyncResult;
    fromAgentDB: Bead[];
  }> {
    this.ensureInitialized();

    this.logger.info('Starting bidirectional sync');

    // First sync from beads to AgentDB
    const allBeads = await this.bdBridge.listBeads({
      after: this.syncState.lastSyncTime,
    });

    const toAgentDBResult = await this.syncToAgentDB(allBeads);

    // Then sync from AgentDB to beads
    const fromAgentDBBeads = await this.syncFromAgentDB();

    return {
      toAgentDB: toAgentDBResult,
      fromAgentDB: fromAgentDBBeads,
    };
  }

  /**
   * Get pending conflicts
   */
  getPendingConflicts(): SyncConflict[] {
    return Array.from(this.conflicts.values()).filter(
      c => c.resolution === 'pending' || !c.resolution
    );
  }

  /**
   * Resolve a specific conflict manually
   */
  async resolveConflictManually(
    beadId: string,
    resolution: 'beads' | 'agentdb' | 'merged',
    mergedData?: Partial<Bead>
  ): Promise<void> {
    const conflict = this.conflicts.get(beadId);
    if (!conflict) {
      throw new SyncBridgeError(
        `No conflict found for bead: ${beadId}`,
        'VALIDATION_ERROR'
      );
    }

    const key = this.beadToKey(conflict.beadData);

    switch (resolution) {
      case 'beads':
        await this.agentDB.store(
          key,
          this.beadToAgentDBValue(conflict.beadData),
          this.config.agentdbNamespace,
          this.buildMetadata(conflict.beadData)
        );
        break;

      case 'agentdb':
        // AgentDB data is already stored, nothing to do
        break;

      case 'merged':
        if (!mergedData) {
          throw new SyncBridgeError(
            'Merged data required for merge resolution',
            'VALIDATION_ERROR'
          );
        }
        const merged = { ...conflict.beadData, ...mergedData };
        await this.agentDB.store(
          key,
          this.beadToAgentDBValue(merged as Bead),
          this.config.agentdbNamespace,
          this.buildMetadata(merged as Bead)
        );
        break;
    }

    conflict.resolution = resolution;
    conflict.resolvedAt = new Date().toISOString();

    // Remove from pending
    const pendingIndex = this.syncState.pendingConflicts.indexOf(beadId);
    if (pendingIndex !== -1) {
      this.syncState.pendingConflicts.splice(pendingIndex, 1);
      await this.saveSyncState();
    }

    this.logger.info(`Conflict resolved for bead ${beadId}`, { resolution });
  }

  /**
   * Get sync state
   */
  getSyncState(): Readonly<SyncState> {
    return { ...this.syncState };
  }

  /**
   * Get sync statistics
   */
  async getSyncStats(): Promise<{
    agentdbCount: number;
    lastSyncTime: string;
    pendingConflicts: number;
    syncVersion: number;
  }> {
    this.ensureInitialized();

    const stats = await this.agentDB.getNamespaceStats(this.config.agentdbNamespace);

    return {
      agentdbCount: stats.count,
      lastSyncTime: this.syncState.lastSyncTime,
      pendingConflicts: this.syncState.pendingConflicts.length,
      syncVersion: this.syncState.version,
    };
  }

  // ============================================================================
  // Private Methods
  // ============================================================================

  /**
   * Convert bead to AgentDB key
   */
  private beadToKey(bead: Bead): string {
    return `bead:${bead.id}`;
  }

  /**
   * Convert bead to AgentDB value
   */
  private beadToAgentDBValue(bead: Bead): Record<string, unknown> {
    const value: Record<string, unknown> = {
      id: bead.id,
      type: bead.type,
      content: bead.content,
      timestamp: bead.timestamp,
      parentId: bead.parentId,
      threadId: bead.threadId,
      agentId: bead.agentId,
      tags: bead.tags,
      hash: bead.hash,
    };

    if (this.config.preserveEmbeddings && bead.embedding) {
      value.embedding = bead.embedding;
    }

    if (this.config.syncMetadata && bead.metadata) {
      value.metadata = bead.metadata;
    }

    return value;
  }

  /**
   * Build metadata for AgentDB entry
   */
  private buildMetadata(bead: Bead): Record<string, unknown> {
    return {
      beadType: bead.type,
      threadId: bead.threadId,
      agentId: bead.agentId,
      syncedAt: new Date().toISOString(),
      syncVersion: this.syncState.version,
    };
  }

  /**
   * Convert AgentDB entry to Bead
   */
  private agentDBToBead(entry: AgentDBEntry): Bead | null {
    if (!entry.value || typeof entry.value !== 'object') {
      return null;
    }

    const data = entry.value as Record<string, unknown>;

    // Validate required fields
    if (!data.id || !data.type || !data.content) {
      return null;
    }

    return {
      id: String(data.id),
      type: data.type as BeadType,
      content: String(data.content),
      timestamp: data.timestamp as string | undefined,
      parentId: data.parentId as string | undefined,
      threadId: data.threadId as string | undefined,
      agentId: data.agentId as string | undefined,
      tags: data.tags as string[] | undefined,
      metadata: data.metadata as Record<string, unknown> | undefined,
      embedding: data.embedding as number[] | undefined,
      hash: data.hash as string | undefined,
    };
  }

  /**
   * Detect if there's a conflict between bead and AgentDB entry
   */
  private async detectConflict(bead: Bead, entry: AgentDBEntry): Promise<boolean> {
    if (!entry.value || typeof entry.value !== 'object') {
      return false;
    }

    const data = entry.value as Record<string, unknown>;

    // No conflict if content is the same
    if (data.content === bead.content) {
      return false;
    }

    // Check timestamps
    const beadTime = bead.timestamp ? new Date(bead.timestamp).getTime() : 0;
    const entryTime = entry.updatedAt ? new Date(entry.updatedAt).getTime() : 0;

    // If bead is newer, no conflict - it should update
    if (beadTime > entryTime) {
      return false;
    }

    // If AgentDB is newer and content differs, conflict
    if (entryTime > beadTime && data.content !== bead.content) {
      return true;
    }

    return false;
  }

  /**
   * Resolve conflict based on strategy
   */
  private async resolveConflict(bead: Bead, entry: AgentDBEntry): Promise<boolean> {
    const conflict: SyncConflict = {
      beadId: bead.id,
      beadData: bead,
      agentdbData: entry,
      conflictType: 'update',
    };

    switch (this.config.conflictStrategy) {
      case 'beads-wins':
        conflict.resolution = 'beads';
        this.conflicts.set(bead.id, conflict);
        return true;

      case 'agentdb-wins':
        conflict.resolution = 'agentdb';
        this.conflicts.set(bead.id, conflict);
        return false; // Don't update AgentDB

      case 'newest-wins': {
        const beadTime = bead.timestamp ? new Date(bead.timestamp).getTime() : 0;
        const entryTime = entry.updatedAt ? new Date(entry.updatedAt).getTime() : 0;

        if (beadTime >= entryTime) {
          conflict.resolution = 'beads';
          this.conflicts.set(bead.id, conflict);
          return true;
        } else {
          conflict.resolution = 'agentdb';
          this.conflicts.set(bead.id, conflict);
          return false;
        }
      }

      case 'merge': {
        // Simple merge: keep both contents with separator
        const entryData = entry.value as Record<string, unknown>;
        const mergedBead: Bead = {
          ...bead,
          content: `${bead.content}\n---\n${entryData.content}`,
          metadata: {
            ...bead.metadata,
            merged: true,
            mergedAt: new Date().toISOString(),
          },
        };
        conflict.beadData = mergedBead;
        conflict.resolution = 'merged';
        this.conflicts.set(bead.id, conflict);
        return true;
      }

      case 'manual':
        conflict.resolution = 'pending';
        this.conflicts.set(bead.id, conflict);
        this.syncState.pendingConflicts.push(bead.id);
        return false;

      default:
        return false;
    }
  }

  /**
   * Save sync state to AgentDB
   */
  private async saveSyncState(): Promise<void> {
    try {
      await this.agentDB.store(
        '_sync_state',
        this.syncState,
        this.config.agentdbNamespace,
        { type: 'sync-state' }
      );
    } catch (error) {
      this.logger.error('Failed to save sync state', {
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  /**
   * Ensure bridge is initialized
   */
  private ensureInitialized(): void {
    if (!this.initialized) {
      throw new SyncBridgeError(
        'Sync bridge not initialized. Call initialize() first.',
        'NOT_INITIALIZED'
      );
    }
  }

  /**
   * Check if bridge is initialized
   */
  isInitialized(): boolean {
    return this.initialized;
  }

  /**
   * Get beads bridge instance
   */
  getBeadsBridge(): BdBridge {
    return this.bdBridge;
  }

  /**
   * Get cache statistics for performance monitoring
   */
  getCacheStats(): {
    agentDBLookupCache: { entries: number; sizeBytes: number };
    conflictCache: { entries: number; sizeBytes: number };
  } {
    return {
      agentDBLookupCache: agentDBLookupCache.stats(),
      conflictCache: conflictCache.stats(),
    };
  }

  /**
   * Clear all sync caches
   */
  clearCaches(): void {
    agentDBLookupCache.clear();
    conflictCache.clear();
  }
}

/**
 * Create a new sync bridge instance
 */
export function createSyncBridge(
  agentDB: IAgentDBService,
  config?: SyncBridgeConfig,
  logger?: SyncLogger
): SyncBridge {
  return new SyncBridge(agentDB, config, logger);
}

// Export schemas for external use
export {
  ConflictStrategySchema,
  SyncDirectionSchema,
  SyncStatusSchema,
  AgentDBEntrySchema,
};

export default SyncBridge;

/**
 * Gas Town Bridge Plugin - Unified Cache System
 *
 * High-performance caching with:
 * - O(1) LRU cache with Map + doubly linked list
 * - WeakMap for formula AST caching (GC-friendly)
 * - Result memoization for expensive operations
 * - Batch deduplication for concurrent requests
 *
 * Performance targets:
 * - 50% memory reduction via eviction
 * - 3x faster cold start via preloading
 *
 * @module gastown-bridge/cache
 * @version 0.1.0
 */

// ============================================================================
// LRU Cache Implementation - O(1) get/set
// ============================================================================

/**
 * Doubly linked list node for LRU tracking
 */
interface LRUNode<K, V> {
  key: K;
  value: V;
  prev: LRUNode<K, V> | null;
  next: LRUNode<K, V> | null;
  size: number;
  createdAt: number;
  accessCount: number;
}

/**
 * LRU Cache with O(1) operations
 *
 * Uses Map for O(1) lookups and doubly linked list for O(1) eviction.
 * Supports TTL, size limits, and access tracking.
 *
 * @example
 * ```typescript
 * const cache = new LRUCache<string, Formula>({ maxSize: 1000, ttlMs: 60000 });
 * cache.set('formula-1', parsedFormula);
 * const formula = cache.get('formula-1');
 * ```
 */
export class LRUCache<K, V> {
  private readonly cache: Map<K, LRUNode<K, V>> = new Map();
  private head: LRUNode<K, V> | null = null;
  private tail: LRUNode<K, V> | null = null;
  private currentSize = 0;

  private readonly maxSize: number;
  private readonly maxEntries: number;
  private readonly ttlMs: number;
  private readonly onEvict?: (key: K, value: V) => void;

  constructor(options: {
    maxSize?: number;
    maxEntries?: number;
    ttlMs?: number;
    onEvict?: (key: K, value: V) => void;
  } = {}) {
    this.maxSize = options.maxSize ?? 50 * 1024 * 1024; // 50MB default
    this.maxEntries = options.maxEntries ?? 1000;
    this.ttlMs = options.ttlMs ?? 0; // 0 = no TTL
    this.onEvict = options.onEvict;
  }

  /**
   * Get value from cache - O(1)
   */
  get(key: K): V | undefined {
    const node = this.cache.get(key);
    if (!node) return undefined;

    // Check TTL
    if (this.ttlMs > 0 && Date.now() - node.createdAt > this.ttlMs) {
      this.delete(key);
      return undefined;
    }

    // Move to front (most recently used)
    this.moveToFront(node);
    node.accessCount++;
    return node.value;
  }

  /**
   * Set value in cache - O(1)
   */
  set(key: K, value: V, sizeBytes?: number): void {
    const size = sizeBytes ?? this.estimateSize(value);

    // Check if key exists - update in place
    const existing = this.cache.get(key);
    if (existing) {
      this.currentSize -= existing.size;
      existing.value = value;
      existing.size = size;
      existing.createdAt = Date.now();
      this.currentSize += size;
      this.moveToFront(existing);
      return;
    }

    // Evict if necessary
    while (
      (this.cache.size >= this.maxEntries || this.currentSize + size > this.maxSize) &&
      this.tail
    ) {
      this.evictLRU();
    }

    // Create new node
    const node: LRUNode<K, V> = {
      key,
      value,
      prev: null,
      next: this.head,
      size,
      createdAt: Date.now(),
      accessCount: 1,
    };

    // Insert at front
    if (this.head) {
      this.head.prev = node;
    }
    this.head = node;
    if (!this.tail) {
      this.tail = node;
    }

    this.cache.set(key, node);
    this.currentSize += size;
  }

  /**
   * Check if key exists - O(1)
   */
  has(key: K): boolean {
    const node = this.cache.get(key);
    if (!node) return false;

    // Check TTL
    if (this.ttlMs > 0 && Date.now() - node.createdAt > this.ttlMs) {
      this.delete(key);
      return false;
    }

    return true;
  }

  /**
   * Delete from cache - O(1)
   */
  delete(key: K): boolean {
    const node = this.cache.get(key);
    if (!node) return false;

    this.removeNode(node);
    this.cache.delete(key);
    this.currentSize -= node.size;
    return true;
  }

  /**
   * Clear all entries
   */
  clear(): void {
    if (this.onEvict) {
      for (const [key, node] of this.cache) {
        this.onEvict(key, node.value);
      }
    }
    this.cache.clear();
    this.head = null;
    this.tail = null;
    this.currentSize = 0;
  }

  /**
   * Get cache stats
   */
  stats(): {
    entries: number;
    sizeBytes: number;
    maxEntries: number;
    maxSizeBytes: number;
    hitRate: number;
  } {
    let totalAccess = 0;
    for (const node of this.cache.values()) {
      totalAccess += node.accessCount;
    }

    return {
      entries: this.cache.size,
      sizeBytes: this.currentSize,
      maxEntries: this.maxEntries,
      maxSizeBytes: this.maxSize,
      hitRate: this.cache.size > 0 ? totalAccess / this.cache.size : 0,
    };
  }

  /**
   * Get all keys (for iteration)
   */
  keys(): IterableIterator<K> {
    return this.cache.keys();
  }

  /**
   * Get size
   */
  get size(): number {
    return this.cache.size;
  }

  // Private methods

  private moveToFront(node: LRUNode<K, V>): void {
    if (node === this.head) return;

    // Remove from current position
    this.removeNode(node);

    // Insert at front
    node.prev = null;
    node.next = this.head;
    if (this.head) {
      this.head.prev = node;
    }
    this.head = node;
    if (!this.tail) {
      this.tail = node;
    }
  }

  private removeNode(node: LRUNode<K, V>): void {
    if (node.prev) {
      node.prev.next = node.next;
    } else {
      this.head = node.next;
    }

    if (node.next) {
      node.next.prev = node.prev;
    } else {
      this.tail = node.prev;
    }
  }

  private evictLRU(): void {
    if (!this.tail) return;

    const evicted = this.tail;
    this.removeNode(evicted);
    this.cache.delete(evicted.key);
    this.currentSize -= evicted.size;

    if (this.onEvict) {
      this.onEvict(evicted.key, evicted.value);
    }
  }

  private estimateSize(value: V): number {
    if (value === null || value === undefined) return 8;
    if (typeof value === 'string') return value.length * 2;
    if (typeof value === 'number') return 8;
    if (typeof value === 'boolean') return 4;
    if (ArrayBuffer.isView(value)) return value.byteLength;
    if (Array.isArray(value)) {
      return value.reduce((acc, v) => acc + this.estimateSize(v), 64);
    }
    if (typeof value === 'object') {
      return JSON.stringify(value).length * 2;
    }
    return 64;
  }
}

// ============================================================================
// Formula AST Cache with WeakMap (GC-friendly)
// ============================================================================

/**
 * Formula AST cache using WeakMap for automatic GC
 *
 * Stores parsed ASTs keyed by source string reference.
 * When the source string is no longer referenced, the AST is GC'd.
 */
export class FormulaASTCache {
  // Use a Map with string keys since TOML content is the key
  // WeakMap only works with object keys
  private readonly astCache: LRUCache<string, unknown>;
  private readonly hashCache: Map<string, string> = new Map();

  constructor(maxEntries = 500) {
    this.astCache = new LRUCache<string, unknown>({
      maxEntries,
      ttlMs: 5 * 60 * 1000, // 5 minute TTL
    });
  }

  /**
   * Get cached AST for formula content
   */
  get(content: string): unknown | undefined {
    const hash = this.hashContent(content);
    return this.astCache.get(hash);
  }

  /**
   * Cache AST for formula content
   */
  set(content: string, ast: unknown): void {
    const hash = this.hashContent(content);
    this.astCache.set(hash, ast);
  }

  /**
   * Check if content has cached AST
   */
  has(content: string): boolean {
    const hash = this.hashContent(content);
    return this.astCache.has(hash);
  }

  /**
   * Clear cache
   */
  clear(): void {
    this.astCache.clear();
    this.hashCache.clear();
  }

  /**
   * Get stats
   */
  stats(): { entries: number; sizeBytes: number } {
    const cacheStats = this.astCache.stats();
    return {
      entries: cacheStats.entries,
      sizeBytes: cacheStats.sizeBytes,
    };
  }

  // Simple hash for content deduplication
  private hashContent(content: string): string {
    const cached = this.hashCache.get(content);
    if (cached) return cached;

    // FNV-1a hash
    let hash = 2166136261;
    for (let i = 0; i < content.length; i++) {
      hash ^= content.charCodeAt(i);
      hash = (hash * 16777619) >>> 0;
    }

    const hashStr = hash.toString(36);
    this.hashCache.set(content, hashStr);

    // Limit hash cache size
    if (this.hashCache.size > 10000) {
      const first = this.hashCache.keys().next().value;
      if (first) this.hashCache.delete(first);
    }

    return hashStr;
  }
}

// ============================================================================
// Result Cache for WASM Operations
// ============================================================================

/**
 * Result cache for expensive WASM operations
 *
 * Caches:
 * - Formula parse results
 * - Cook results
 * - Graph analysis results (topo sort, cycle detection)
 */
export class ResultCache {
  readonly formulas: LRUCache<string, unknown>;
  readonly cooked: LRUCache<string, unknown>;
  readonly beads: LRUCache<string, unknown>;
  readonly convoys: LRUCache<string, unknown>;
  readonly graphs: LRUCache<string, unknown>;

  constructor(options: {
    maxFormulaEntries?: number;
    maxCookedEntries?: number;
    maxBeadEntries?: number;
    maxConvoyEntries?: number;
    maxGraphEntries?: number;
  } = {}) {
    this.formulas = new LRUCache({
      maxEntries: options.maxFormulaEntries ?? 200,
      ttlMs: 10 * 60 * 1000, // 10 min
    });

    this.cooked = new LRUCache({
      maxEntries: options.maxCookedEntries ?? 500,
      ttlMs: 5 * 60 * 1000, // 5 min
    });

    this.beads = new LRUCache({
      maxEntries: options.maxBeadEntries ?? 1000,
      ttlMs: 60 * 1000, // 1 min - beads change frequently
    });

    this.convoys = new LRUCache({
      maxEntries: options.maxConvoyEntries ?? 100,
      ttlMs: 30 * 1000, // 30 sec - convoys update often
    });

    this.graphs = new LRUCache({
      maxEntries: options.maxGraphEntries ?? 100,
      ttlMs: 2 * 60 * 1000, // 2 min
    });
  }

  /**
   * Clear all caches
   */
  clearAll(): void {
    this.formulas.clear();
    this.cooked.clear();
    this.beads.clear();
    this.convoys.clear();
    this.graphs.clear();
  }

  /**
   * Get combined stats
   */
  stats(): Record<string, { entries: number; sizeBytes: number }> {
    return {
      formulas: this.formulas.stats(),
      cooked: this.cooked.stats(),
      beads: this.beads.stats(),
      convoys: this.convoys.stats(),
      graphs: this.graphs.stats(),
    };
  }
}

// ============================================================================
// Batch Deduplication for Concurrent Requests
// ============================================================================

/**
 * Pending request tracker for batch deduplication
 */
interface PendingRequest<T> {
  promise: Promise<T>;
  resolvers: Array<{
    resolve: (value: T) => void;
    reject: (error: unknown) => void;
  }>;
  startedAt: number;
}

/**
 * Batch deduplicator for concurrent identical requests
 *
 * When multiple callers request the same operation simultaneously,
 * only one actual execution occurs and all callers receive the same result.
 *
 * @example
 * ```typescript
 * const dedup = new BatchDeduplicator<Formula>();
 *
 * // These concurrent calls will only execute once
 * const [r1, r2, r3] = await Promise.all([
 *   dedup.dedupe('formula-1', () => parseFormula(content)),
 *   dedup.dedupe('formula-1', () => parseFormula(content)),
 *   dedup.dedupe('formula-1', () => parseFormula(content)),
 * ]);
 * ```
 */
export class BatchDeduplicator<T> {
  private pending: Map<string, PendingRequest<T>> = new Map();
  private readonly timeoutMs: number;

  constructor(timeoutMs = 30000) {
    this.timeoutMs = timeoutMs;
  }

  /**
   * Deduplicate concurrent requests for the same key
   */
  async dedupe(key: string, executor: () => Promise<T>): Promise<T> {
    // Check for existing pending request
    const existing = this.pending.get(key);
    if (existing) {
      // Join existing request
      return new Promise<T>((resolve, reject) => {
        existing.resolvers.push({ resolve, reject });
      });
    }

    // Create new pending request
    let resolvers: PendingRequest<T>['resolvers'] = [];

    const promise = (async () => {
      try {
        const result = await executor();

        // Resolve all waiters
        for (const { resolve } of resolvers) {
          resolve(result);
        }

        return result;
      } catch (error) {
        // Reject all waiters
        for (const { reject } of resolvers) {
          reject(error);
        }
        throw error;
      } finally {
        this.pending.delete(key);
      }
    })();

    const pendingRequest: PendingRequest<T> = {
      promise,
      resolvers,
      startedAt: Date.now(),
    };

    this.pending.set(key, pendingRequest);

    // Set timeout to prevent stuck requests
    setTimeout(() => {
      const req = this.pending.get(key);
      if (req === pendingRequest) {
        this.pending.delete(key);
        for (const { reject } of req.resolvers) {
          reject(new Error(`Request timed out after ${this.timeoutMs}ms`));
        }
      }
    }, this.timeoutMs);

    return promise;
  }

  /**
   * Get number of pending requests
   */
  get pendingCount(): number {
    return this.pending.size;
  }

  /**
   * Clear all pending requests (reject with error)
   */
  clear(): void {
    for (const [key, req] of this.pending) {
      for (const { reject } of req.resolvers) {
        reject(new Error('Deduplicator cleared'));
      }
    }
    this.pending.clear();
  }
}

// ============================================================================
// Preloader for Idle-Time Module Loading
// ============================================================================

/**
 * Idle-time module preloader
 *
 * Preloads WASM modules and other resources during browser/Node idle time.
 */
export class ModulePreloader {
  private readonly preloadQueue: Array<{
    name: string;
    loader: () => Promise<unknown>;
    priority: number;
  }> = [];

  private readonly loaded: Map<string, unknown> = new Map();
  private readonly errors: Map<string, Error> = new Map();
  private isPreloading = false;
  private preloadPromise: Promise<void> | null = null;

  /**
   * Register a module for preloading
   */
  register(
    name: string,
    loader: () => Promise<unknown>,
    priority = 0
  ): void {
    if (this.loaded.has(name)) return;

    this.preloadQueue.push({ name, loader, priority });
    this.preloadQueue.sort((a, b) => b.priority - a.priority);
  }

  /**
   * Start preloading during idle time
   */
  async startPreload(): Promise<void> {
    if (this.isPreloading || this.preloadQueue.length === 0) return;

    this.isPreloading = true;
    this.preloadPromise = this.runPreload();

    try {
      await this.preloadPromise;
    } finally {
      this.isPreloading = false;
      this.preloadPromise = null;
    }
  }

  /**
   * Get preloaded module
   */
  get<T>(name: string): T | undefined {
    return this.loaded.get(name) as T | undefined;
  }

  /**
   * Check if module is loaded
   */
  isLoaded(name: string): boolean {
    return this.loaded.has(name);
  }

  /**
   * Get loading error if any
   */
  getError(name: string): Error | undefined {
    return this.errors.get(name);
  }

  /**
   * Get preload status
   */
  status(): {
    queued: number;
    loaded: number;
    errors: number;
    isPreloading: boolean;
  } {
    return {
      queued: this.preloadQueue.length,
      loaded: this.loaded.size,
      errors: this.errors.size,
      isPreloading: this.isPreloading,
    };
  }

  /**
   * Wait for preloading to complete
   */
  async waitForPreload(): Promise<void> {
    if (this.preloadPromise) {
      await this.preloadPromise;
    }
  }

  private async runPreload(): Promise<void> {
    while (this.preloadQueue.length > 0) {
      const item = this.preloadQueue.shift();
      if (!item) break;

      // Use requestIdleCallback in browser, setImmediate in Node
      await this.scheduleIdleTask(async () => {
        try {
          const module = await item.loader();
          this.loaded.set(item.name, module);
        } catch (error) {
          this.errors.set(item.name, error as Error);
        }
      });
    }
  }

  private scheduleIdleTask(task: () => Promise<void>): Promise<void> {
    return new Promise((resolve) => {
      if (typeof requestIdleCallback !== 'undefined') {
        requestIdleCallback(async () => {
          await task();
          resolve();
        });
      } else if (typeof setImmediate !== 'undefined') {
        setImmediate(async () => {
          await task();
          resolve();
        });
      } else {
        setTimeout(async () => {
          await task();
          resolve();
        }, 0);
      }
    });
  }
}

// ============================================================================
// Connection Pool for CLI Execution
// ============================================================================

/**
 * Pooled resource wrapper
 */
interface PooledResource<T> {
  resource: T;
  inUse: boolean;
  createdAt: number;
  lastUsedAt: number;
  useCount: number;
}

/**
 * Generic connection/resource pool
 *
 * Manages a pool of reusable resources like CLI processes or connections.
 */
export class ResourcePool<T> {
  private pool: PooledResource<T>[] = [];
  private waitQueue: Array<{
    resolve: (resource: T) => void;
    reject: (error: Error) => void;
    timeoutId: NodeJS.Timeout;
  }> = [];

  private readonly create: () => Promise<T>;
  private readonly destroy: (resource: T) => Promise<void>;
  private readonly validate: (resource: T) => boolean;

  private readonly minSize: number;
  private readonly maxSize: number;
  private readonly acquireTimeoutMs: number;
  private readonly idleTimeoutMs: number;

  constructor(options: {
    create: () => Promise<T>;
    destroy: (resource: T) => Promise<void>;
    validate?: (resource: T) => boolean;
    minSize?: number;
    maxSize?: number;
    acquireTimeoutMs?: number;
    idleTimeoutMs?: number;
  }) {
    this.create = options.create;
    this.destroy = options.destroy;
    this.validate = options.validate ?? (() => true);
    this.minSize = options.minSize ?? 1;
    this.maxSize = options.maxSize ?? 10;
    this.acquireTimeoutMs = options.acquireTimeoutMs ?? 5000;
    this.idleTimeoutMs = options.idleTimeoutMs ?? 60000;

    // Start idle cleanup timer
    setInterval(() => this.cleanupIdle(), this.idleTimeoutMs / 2);
  }

  /**
   * Acquire a resource from the pool
   */
  async acquire(): Promise<T> {
    // Try to find an available resource
    for (const pooled of this.pool) {
      if (!pooled.inUse && this.validate(pooled.resource)) {
        pooled.inUse = true;
        pooled.lastUsedAt = Date.now();
        pooled.useCount++;
        return pooled.resource;
      }
    }

    // Create new resource if under max
    if (this.pool.length < this.maxSize) {
      const resource = await this.create();
      const pooled: PooledResource<T> = {
        resource,
        inUse: true,
        createdAt: Date.now(),
        lastUsedAt: Date.now(),
        useCount: 1,
      };
      this.pool.push(pooled);
      return resource;
    }

    // Wait for available resource
    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        const index = this.waitQueue.findIndex((w) => w.resolve === resolve);
        if (index !== -1) {
          this.waitQueue.splice(index, 1);
        }
        reject(new Error('Acquire timeout'));
      }, this.acquireTimeoutMs);

      this.waitQueue.push({ resolve, reject, timeoutId });
    });
  }

  /**
   * Release a resource back to the pool
   */
  release(resource: T): void {
    const pooled = this.pool.find((p) => p.resource === resource);
    if (!pooled) return;

    pooled.inUse = false;
    pooled.lastUsedAt = Date.now();

    // Check if anyone is waiting
    if (this.waitQueue.length > 0) {
      const waiter = this.waitQueue.shift();
      if (waiter && this.validate(resource)) {
        clearTimeout(waiter.timeoutId);
        pooled.inUse = true;
        pooled.useCount++;
        waiter.resolve(resource);
      }
    }
  }

  /**
   * Execute with automatic acquire/release
   */
  async withResource<R>(fn: (resource: T) => Promise<R>): Promise<R> {
    const resource = await this.acquire();
    try {
      return await fn(resource);
    } finally {
      this.release(resource);
    }
  }

  /**
   * Get pool stats
   */
  stats(): {
    total: number;
    inUse: number;
    available: number;
    waiting: number;
  } {
    const inUse = this.pool.filter((p) => p.inUse).length;
    return {
      total: this.pool.length,
      inUse,
      available: this.pool.length - inUse,
      waiting: this.waitQueue.length,
    };
  }

  /**
   * Shutdown the pool
   */
  async shutdown(): Promise<void> {
    // Reject all waiters
    for (const waiter of this.waitQueue) {
      clearTimeout(waiter.timeoutId);
      waiter.reject(new Error('Pool shutdown'));
    }
    this.waitQueue = [];

    // Destroy all resources
    for (const pooled of this.pool) {
      try {
        await this.destroy(pooled.resource);
      } catch {
        // Ignore destruction errors
      }
    }
    this.pool = [];
  }

  private async cleanupIdle(): Promise<void> {
    const now = Date.now();
    const toRemove: PooledResource<T>[] = [];

    for (const pooled of this.pool) {
      if (
        !pooled.inUse &&
        now - pooled.lastUsedAt > this.idleTimeoutMs &&
        this.pool.length > this.minSize
      ) {
        toRemove.push(pooled);
      }
    }

    for (const pooled of toRemove) {
      const index = this.pool.indexOf(pooled);
      if (index !== -1) {
        this.pool.splice(index, 1);
        try {
          await this.destroy(pooled.resource);
        } catch {
          // Ignore
        }
      }
    }
  }
}

// ============================================================================
// Debounced Progress Updates
// ============================================================================

/**
 * Debounced update emitter
 *
 * Batches rapid updates and emits at most once per interval.
 */
export class DebouncedEmitter<T> {
  private pending: T | null = null;
  private timeoutId: NodeJS.Timeout | null = null;
  private lastEmitTime = 0;

  constructor(
    private readonly emit: (value: T) => void,
    private readonly debounceMs: number = 100
  ) {}

  /**
   * Schedule an update (debounced)
   */
  update(value: T): void {
    this.pending = value;

    const now = Date.now();
    const timeSinceLastEmit = now - this.lastEmitTime;

    // If enough time has passed, emit immediately
    if (timeSinceLastEmit >= this.debounceMs) {
      this.flush();
      return;
    }

    // Otherwise, schedule for later
    if (!this.timeoutId) {
      this.timeoutId = setTimeout(() => {
        this.flush();
      }, this.debounceMs - timeSinceLastEmit);
    }
  }

  /**
   * Flush pending update immediately
   */
  flush(): void {
    if (this.timeoutId) {
      clearTimeout(this.timeoutId);
      this.timeoutId = null;
    }

    if (this.pending !== null) {
      this.emit(this.pending);
      this.pending = null;
      this.lastEmitTime = Date.now();
    }
  }

  /**
   * Cancel pending update
   */
  cancel(): void {
    if (this.timeoutId) {
      clearTimeout(this.timeoutId);
      this.timeoutId = null;
    }
    this.pending = null;
  }
}

// ============================================================================
// Lazy Parser - Parse on Access
// ============================================================================

/**
 * Lazy value wrapper - computes value on first access
 */
export class Lazy<T> {
  private computed = false;
  private value: T | undefined;
  private error: Error | undefined;

  constructor(private readonly factory: () => T) {}

  /**
   * Get the value (computes on first access)
   */
  get(): T {
    if (!this.computed) {
      try {
        this.value = this.factory();
      } catch (e) {
        this.error = e as Error;
      }
      this.computed = true;
    }

    if (this.error) {
      throw this.error;
    }

    return this.value!;
  }

  /**
   * Check if value has been computed
   */
  get isComputed(): boolean {
    return this.computed;
  }

  /**
   * Reset to uncomputed state
   */
  reset(): void {
    this.computed = false;
    this.value = undefined;
    this.error = undefined;
  }
}

/**
 * Async lazy value wrapper
 */
export class AsyncLazy<T> {
  private promise: Promise<T> | null = null;
  private value: T | undefined;
  private resolved = false;

  constructor(private readonly factory: () => Promise<T>) {}

  /**
   * Get the value (computes on first access)
   */
  async get(): Promise<T> {
    if (this.resolved) {
      return this.value!;
    }

    if (!this.promise) {
      this.promise = this.factory().then((v) => {
        this.value = v;
        this.resolved = true;
        return v;
      });
    }

    return this.promise;
  }

  /**
   * Check if value has been resolved
   */
  get isResolved(): boolean {
    return this.resolved;
  }

  /**
   * Reset to uncomputed state
   */
  reset(): void {
    this.promise = null;
    this.value = undefined;
    this.resolved = false;
  }
}

