const ConvoyIdSchema = z.string().uuid('Invalid convoy ID format');

// ============================================================================
// Convoy Observer Implementation
// ============================================================================

/**
 * Convoy Observer
 *
 * Monitors convoys for completion and provides dependency analysis.
 *
 * @example
 * ```typescript
 * const observer = new ConvoyObserver({
 *   bdBridge,
 *   tracker,
 *   pollInterval: 5000,
 *   useWasm: true,
 * });
 *
 * // Watch for completion
 * const handle = observer.watch(convoyId, (convoy, complete) => {
 *   if (complete) {
 *     console.log('Convoy complete!');
 *   }
 * });
 *
 * // Check blockers
 * const blockers = await observer.getBlockers(convoyId);
 *
 * // Get ready issues
 * const ready = await observer.getReadyIssues(convoyId);
 *
 * // Stop watching
 * handle.stop();
 * ```
 */
export class ConvoyObserver extends EventEmitter {
  private bdBridge: BdBridge;
  private tracker: ConvoyTracker;
  private wasmModule?: WasmGraphModule;
  private logger: ObserverLogger;
  private config: Required<Omit<ConvoyObserverConfig, 'bdBridge' | 'tracker' | 'wasmModule'>>;
  private watchers: Map<string, {
    timer: NodeJS.Timeout;
    callback: CompletionCallback;
    attempts: number;
    currentInterval: number;
    lastState: string | null;
  }> = new Map();

  // Performance optimization caches
  private readonly beadCache: LRUCache<string, Bead>;
  private readonly completionCache: LRUCache<string, CompletionCheckResult>;
  private readonly fetchDedup: BatchDeduplicator<Bead[]>;
  private readonly progressEmitters: Map<string, DebouncedEmitter<ConvoyProgress>>;

  // Subscription batching
  private pendingSubscriptions: Map<string, Set<CompletionCallback>> = new Map();
  private subscriptionFlushTimer: NodeJS.Timeout | null = null;

  constructor(config: ConvoyObserverConfig, logger?: ObserverLogger) {
    super();
    this.bdBridge = config.bdBridge;
    this.tracker = config.tracker;
    this.wasmModule = config.wasmModule;
    this.logger = logger ?? defaultLogger;
    this.config = {
      pollInterval: config.pollInterval ?? 10000,
      maxPollAttempts: config.maxPollAttempts ?? 0, // 0 = unlimited
      useWasm: config.useWasm ?? true,
      useExponentialBackoff: config.useExponentialBackoff ?? true,
      maxBackoffInterval: config.maxBackoffInterval ?? 60000, // 1 minute max
      backoffMultiplier: config.backoffMultiplier ?? 1.5,
      deltaUpdatesOnly: config.deltaUpdatesOnly ?? true,
      progressDebounceMs: config.progressDebounceMs ?? 500,
    };

    // Initialize performance caches
    this.beadCache = new LRUCache<string, Bead>({
      maxEntries: 1000,
      ttlMs: 30 * 1000, // 30 seconds (beads change frequently)
    });

    this.completionCache = new LRUCache<string, CompletionCheckResult>({
      maxEntries: 100,
      ttlMs: 5 * 1000, // 5 seconds (completion state changes)
    });

    this.fetchDedup = new BatchDeduplicator<Bead[]>(30000);
    this.progressEmitters = new Map();
  }

  /**
   * Watch a convoy for completion
   *
   * @param convoyId - Convoy ID to watch
   * @param callback - Called on each check with completion status
   * @returns Watch handle to stop watching
   */
  watch(convoyId: string, callback: CompletionCallback): WatchHandle {
    ConvoyIdSchema.parse(convoyId);

    // Stop existing watcher if any
    this.stopWatching(convoyId);

    const initialInterval = this.config.pollInterval;

    // Create initial polling timer (will be rescheduled with backoff)
    const scheduleNextPoll = (interval: number): NodeJS.Timeout => {
      return setTimeout(async () => {
        await this.pollConvoyWithBackoff(convoyId, callback);
      }, interval);
    };

    const timer = scheduleNextPoll(initialInterval);

    this.watchers.set(convoyId, {
      timer,
      callback,
      attempts: 0,
      currentInterval: initialInterval,
      lastState: null,
    });

    // Create debounced progress emitter for this convoy
    this.progressEmitters.set(
      convoyId,
      new DebouncedEmitter<ConvoyProgress>(
        (progress) => this.emit('progress', convoyId, progress),
        this.config.progressDebounceMs
      )
    );

    // Immediate first check
    this.pollConvoyWithBackoff(convoyId, callback);

    this.logger.info('Started watching convoy', { convoyId, interval: initialInterval });

    return {
      convoyId,
      stop: () => this.stopWatching(convoyId),
      isActive: () => this.watchers.has(convoyId),
    };
  }

  /**
   * Batch subscribe to multiple convoys
   * Subscriptions are batched and flushed together for efficiency
   *
   * @param convoyId - Convoy ID to watch
   * @param callback - Callback for completion status
   */
  batchSubscribe(convoyId: string, callback: CompletionCallback): void {
    if (!this.pendingSubscriptions.has(convoyId)) {
      this.pendingSubscriptions.set(convoyId, new Set());
    }
    this.pendingSubscriptions.get(convoyId)!.add(callback);

    // Flush after a short delay to batch multiple subscriptions
    if (!this.subscriptionFlushTimer) {
      this.subscriptionFlushTimer = setTimeout(() => {
        this.flushSubscriptions();
      }, 50); // 50ms batching window
    }
  }

  /**
   * Flush pending subscriptions
   */
  private flushSubscriptions(): void {
    this.subscriptionFlushTimer = null;

    for (const [convoyId, callbacks] of this.pendingSubscriptions) {
      // Create a merged callback that calls all registered callbacks
      const mergedCallback: CompletionCallback = (convoy, allComplete) => {
        for (const cb of callbacks) {
          try {
            cb(convoy, allComplete);
          } catch (error) {
            this.logger.error('Subscription callback error', {
              convoyId,
              error: error instanceof Error ? error.message : String(error),
            });
          }
        }
      };

      this.watch(convoyId, mergedCallback);
    }

    this.pendingSubscriptions.clear();
    this.logger.debug('Flushed subscription batch', {
      convoys: this.pendingSubscriptions.size,
    });
  }

  /**
   * Check if all issues in a convoy are complete
   *
   * @param convoyId - Convoy ID
   * @returns Completion check result with detailed status
   */
  async checkCompletion(convoyId: string): Promise<CompletionCheckResult> {
    ConvoyIdSchema.parse(convoyId);

    const convoy = this.tracker.getConvoy(convoyId);
    if (!convoy) {
      throw ConvoyError.notFound(convoyId);
    }

    // Fetch all beads
    const beads = await this.fetchBeads(convoy.trackedIssues);
    const beadMap = new Map(beads.map(b => [b.id, b]));

    // Calculate progress
    const openIssues: string[] = [];
    const inProgressIssues: string[] = [];
    let closed = 0;

    for (const issueId of convoy.trackedIssues) {
      const bead = beadMap.get(issueId);
      if (!bead) continue;

      if (bead.status === 'closed') {
        closed++;
      } else if (bead.status === 'in_progress') {
        inProgressIssues.push(issueId);
      } else {
        openIssues.push(issueId);
      }
    }

    // Use WASM for graph analysis if available
    let hasCycles = false;
    let cycleIssues: string[] = [];
    let readyIssues: ReadyIssueInfo[] = [];
    let blockedIssues: BlockerInfo[] = [];

    if (this.config.useWasm && this.wasmModule) {
      try {
        const wasmResult = this.analyzeWithWasm(beads);
        hasCycles = wasmResult.hasCycles;
        cycleIssues = wasmResult.cycleIssues;
        readyIssues = wasmResult.readyIssues;
        blockedIssues = wasmResult.blockedIssues;
      } catch (error) {
        this.logger.warn('WASM analysis failed, falling back to JS', {
          error: error instanceof Error ? error.message : String(error),
        });
        const jsResult = this.analyzeWithJS(beads, convoy.trackedIssues);
        hasCycles = jsResult.hasCycles;
        cycleIssues = jsResult.cycleIssues;
        readyIssues = jsResult.readyIssues;
        blockedIssues = jsResult.blockedIssues;
      }
    } else {
      const jsResult = this.analyzeWithJS(beads, convoy.trackedIssues);
      hasCycles = jsResult.hasCycles;
      cycleIssues = jsResult.cycleIssues;
      readyIssues = jsResult.readyIssues;
      blockedIssues = jsResult.blockedIssues;
    }

    const progress: ConvoyProgress = {
      total: convoy.trackedIssues.length,
      closed,
      inProgress: inProgressIssues.length,
      blocked: blockedIssues.length,
    };

    return {
      allComplete: closed === convoy.trackedIssues.length,
      progress,
      openIssues,
      inProgressIssues,
      blockedIssues,
      readyIssues,
      hasCycles,
      cycleIssues,
    };
  }

  /**
   * Get blockers for all issues in a convoy
   *
   * @param convoyId - Convoy ID
   * @returns Array of blocker information
   */
  async getBlockers(convoyId: string): Promise<BlockerInfo[]> {
    const result = await this.checkCompletion(convoyId);
    return result.blockedIssues;
  }

  /**
   * Get issues ready to work on (no unresolved dependencies)
   *
   * @param convoyId - Convoy ID
   * @returns Array of ready issue information
   */
  async getReadyIssues(convoyId: string): Promise<ReadyIssueInfo[]> {
    const result = await this.checkCompletion(convoyId);
    return result.readyIssues;
  }

  /**
   * Get execution order for convoy issues
   *
   * @param convoyId - Convoy ID
   * @returns Ordered array of issue IDs
   */
  async getExecutionOrder(convoyId: string): Promise<string[]> {
    ConvoyIdSchema.parse(convoyId);

    const convoy = this.tracker.getConvoy(convoyId);
    if (!convoy) {
      throw ConvoyError.notFound(convoyId);
    }

    const beads = await this.fetchBeads(convoy.trackedIssues);

    if (this.config.useWasm && this.wasmModule) {
      try {
        const wasmNodes = this.beadsToWasmNodes(beads);
        const resultJson = this.wasmModule.topo_sort(JSON.stringify(wasmNodes));
        const result: TopoSortResult = JSON.parse(resultJson);

        if (result.hasCycle) {
          throw new GasTownError(
            'Cannot compute execution order: dependency cycle detected',
            GasTownErrorCode.DEPENDENCY_CYCLE,
            { cycleNodes: result.cycleNodes }
          );
        }

        return result.sorted;
      } catch (error) {
        if (error instanceof GasTownError) throw error;
        this.logger.warn('WASM topo sort failed, falling back to JS', {
          error: error instanceof Error ? error.message : String(error),
        });
      }
    }

    // JavaScript fallback using Kahn's algorithm
    return this.topoSortJS(beads);
  }

  /**
   * Stop watching a convoy
   */
  stopWatching(convoyId: string): void {
    const watcher = this.watchers.get(convoyId);
    if (watcher) {
      clearTimeout(watcher.timer);
      this.watchers.delete(convoyId);

      // Clean up progress emitter
      const emitter = this.progressEmitters.get(convoyId);
      if (emitter) {
        emitter.flush(); // Emit any pending updates
        this.progressEmitters.delete(convoyId);
      }

      // Invalidate completion cache for this convoy
      this.completionCache.delete(convoyId);

      this.logger.info('Stopped watching convoy', { convoyId });
    }
  }

  /**
   * Stop all watchers
   */
  stopAll(): void {
    for (const [convoyId, watcher] of this.watchers) {
      clearTimeout(watcher.timer);
    }
    this.watchers.clear();

    // Clean up all progress emitters
    for (const emitter of this.progressEmitters.values()) {
      emitter.flush();
    }
    this.progressEmitters.clear();

    // Clear all caches
    this.beadCache.clear();
    this.completionCache.clear();
    this.fetchDedup.clear();

    // Clear pending subscriptions
    if (this.subscriptionFlushTimer) {
      clearTimeout(this.subscriptionFlushTimer);
      this.subscriptionFlushTimer = null;
    }
    this.pendingSubscriptions.clear();

    this.logger.info('Stopped all convoy watchers');
  }

  /**
   * Set WASM module
   */
  setWasmModule(module: WasmGraphModule): void {
    this.wasmModule = module;
    this.logger.info('WASM module set');
  }

  /**
   * Check if WASM is available
   */
  isWasmAvailable(): boolean {
    return !!this.wasmModule;
  }

  // =========================================================================
  // Private Methods
  // =========================================================================

  /**
   * Poll convoy for completion with exponential backoff
   */
  private async pollConvoyWithBackoff(
    convoyId: string,
    callback: CompletionCallback
  ): Promise<void> {
    const watcher = this.watchers.get(convoyId);
    if (!watcher) return;

    try {
      const convoy = this.tracker.getConvoy(convoyId);
      if (!convoy) {
        this.stopWatching(convoyId);
        return;
      }

      // Skip if already complete
      if (convoy.status === 'landed' || convoy.status === 'failed') {
        callback(convoy, convoy.status === 'landed');
        this.stopWatching(convoyId);
        return;
      }

      const result = await this.checkCompletion(convoyId);

      // Delta-based updates: only emit if state changed
      const currentState = JSON.stringify({
        allComplete: result.allComplete,
        progress: result.progress,
        openIssues: result.openIssues.length,
        inProgress: result.inProgressIssues.length,
        blocked: result.blockedIssues.length,
      });

      const stateChanged = watcher.lastState !== currentState;
      watcher.lastState = currentState;

      if (this.config.deltaUpdatesOnly && !stateChanged) {
        // No state change - increase backoff interval
        if (this.config.useExponentialBackoff) {
          watcher.currentInterval = Math.min(
            watcher.currentInterval * this.config.backoffMultiplier,
            this.config.maxBackoffInterval
          );
        }
      } else {
        // State changed - reset to initial interval and call callback
        watcher.currentInterval = this.config.pollInterval;
        callback(convoy, result.allComplete);

        // Emit debounced progress update
        const emitter = this.progressEmitters.get(convoyId);
        if (emitter) {
          emitter.update(result.progress);
        }
      }

      watcher.attempts++;

      // Check max attempts
      if (
        this.config.maxPollAttempts > 0 &&
        watcher.attempts >= this.config.maxPollAttempts
      ) {
        this.logger.warn('Max poll attempts reached', {
          convoyId,
          attempts: watcher.attempts,
        });
        this.stopWatching(convoyId);
        return;
      }

      // Schedule next poll with current interval (possibly backed off)
      clearTimeout(watcher.timer);
      watcher.timer = setTimeout(async () => {
        await this.pollConvoyWithBackoff(convoyId, callback);
      }, watcher.currentInterval);

    } catch (error) {
      this.logger.error('Poll error', {
        convoyId,
        error: error instanceof Error ? error.message : String(error),
      });

      // On error, increase backoff more aggressively
      if (this.config.useExponentialBackoff) {
        watcher.currentInterval = Math.min(
          watcher.currentInterval * (this.config.backoffMultiplier * 1.5),
          this.config.maxBackoffInterval
        );
      }

      // Schedule retry with backed-off interval
      clearTimeout(watcher.timer);
      watcher.timer = setTimeout(async () => {
        await this.pollConvoyWithBackoff(convoyId, callback);
      }, watcher.currentInterval);
    }
  }

  /**
   * Legacy poll convoy method (without backoff)
   * @deprecated Use pollConvoyWithBackoff instead
   */
  private async pollConvoy(
    convoyId: string,
    callback: CompletionCallback
  ): Promise<void> {
    return this.pollConvoyWithBackoff(convoyId, callback);
  }

  /**
   * Fetch beads by IDs with caching, batch deduplication, and object pooling.
   * Uses PooledBead from memory module for reduced allocations.
   */
  private async fetchBeads(issueIds: string[]): Promise<Bead[]> {
    // Create a batch key for deduplication
    const batchKey = issueIds.sort().join(',');

    return this.fetchDedup.dedupe(batchKey, async () => {
      const beads: Bead[] = [];
      const uncachedIds: string[] = [];

      // Check cache first for each bead
      for (const id of issueIds) {
        const cached = this.beadCache.get(id);
        if (cached) {
          beads.push(cached);
        } else {
          uncachedIds.push(id);
        }
      }

      // Fetch uncached beads in parallel (batch of 10)
      const batchSize = 10;
      for (let i = 0; i < uncachedIds.length; i += batchSize) {
        const batch = uncachedIds.slice(i, i + batchSize);
        const fetchPromises = batch.map(async (id) => {
          try {
            const cliBead = await this.bdBridge.getBead(id);

            // Use pooled bead for reduced allocations
            const pooledBead = beadPool.acquire() as PooledBead;
            pooledBead.id = cliBead.id;
            pooledBead.title = cliBead.content.slice(0, 100);
            pooledBead.description = cliBead.content;
            pooledBead.status = this.mapBeadStatus(cliBead.type);
            pooledBead.priority = 0;
            pooledBead.labels = cliBead.tags ?? [];
            pooledBead.createdAt = cliBead.timestamp ? new Date(cliBead.timestamp) : new Date();
            pooledBead.updatedAt = new Date();
            pooledBead.blockedBy = cliBead.parentId ? [cliBead.parentId] : [];
            pooledBead.blocks = [];

            // Convert to plain Bead object for caching (avoid pool reference issues)
            const bead: Bead = {
              id: pooledBead.id,
              title: pooledBead.title,
              description: pooledBead.description,
              status: pooledBead.status,
              priority: pooledBead.priority,
              labels: pooledBead.labels,
              createdAt: pooledBead.createdAt,
              updatedAt: pooledBead.updatedAt,
              blockedBy: pooledBead.blockedBy,
              blocks: pooledBead.blocks,
            };

            // Release pooled bead back to pool
            beadPool.release(pooledBead);

            // Cache the bead
            this.beadCache.set(id, bead);
            return bead;
          } catch {
            // Skip invalid beads
            return null;
          }
        });

        const results = await Promise.all(fetchPromises);
        beads.push(...results.filter((b): b is Bead => b !== null));
      }

      return beads;
    });
  }

  /**
   * Map CLI bead type to Gas Town status
   */
  private mapBeadStatus(type: string): BeadStatus {
    switch (type) {
      case 'closed':
        return 'closed';
      case 'in_progress':
      case 'response':
      case 'code':
        return 'in_progress';
      default:
        return 'open';
    }
  }

  /**
   * Convert beads to WASM node format
   */
  private beadsToWasmNodes(beads: Bead[]): WasmBeadNode[] {
    return beads.map(bead => ({
      id: bead.id,
      title: bead.title,
      status: bead.status,
      priority: bead.priority,
      blocked_by: bead.blockedBy ?? [],
      blocks: bead.blocks ?? [],
      duration: undefined,
    }));
  }

  /**
   * Analyze dependencies with WASM
   */
  private analyzeWithWasm(beads: Bead[]): {
    hasCycles: boolean;
    cycleIssues: string[];
    readyIssues: ReadyIssueInfo[];
    blockedIssues: BlockerInfo[];
  } {
    if (!this.wasmModule) {
      throw new Error('WASM module not available');
    }

    const wasmNodes = this.beadsToWasmNodes(beads);
    const beadsJson = JSON.stringify(wasmNodes);

    // Check for cycles
    const hasCycles = this.wasmModule.has_cycle(beadsJson);
    let cycleIssues: string[] = [];
    if (hasCycles) {
      const cycleJson = this.wasmModule.find_cycle_nodes(beadsJson);
      cycleIssues = JSON.parse(cycleJson);
    }

    // Get ready beads
    const readyJson = this.wasmModule.get_ready_beads(beadsJson);
    const readyIds: string[] = JSON.parse(readyJson);

    // Get execution levels
    const levelsJson = this.wasmModule.compute_levels(beadsJson);
    const levels: Record<string, string[]> = JSON.parse(levelsJson);

    // Build level map
    const levelMap = new Map<string, number>();
    for (const [levelStr, ids] of Object.entries(levels)) {
      const level = parseInt(levelStr, 10);
      for (const id of ids) {
        levelMap.set(id, level);
      }
    }

    // Build ready issues with level info
    const beadMap = new Map(beads.map(b => [b.id, b]));
    const readyIssues: ReadyIssueInfo[] = readyIds.map(id => {
      const bead = beadMap.get(id)!;
      return {
        id,
        title: bead.title,
        priority: bead.priority,
        level: levelMap.get(id) ?? 0,
      };
    });

    // Find blocked issues
    const closedSet = new Set(
      beads.filter(b => b.status === 'closed').map(b => b.id)
    );
    const convoySet = new Set(beads.map(b => b.id));

    const blockedIssues: BlockerInfo[] = beads
      .filter(bead => {
        if (bead.status === 'closed') return false;
        const blockers = bead.blockedBy ?? [];
        return blockers.some(blockerId => !closedSet.has(blockerId));
      })
      .map(bead => {
        const blockers = (bead.blockedBy ?? []).filter(
          id => !closedSet.has(id)
        );
        const internalBlockers = blockers.every(id => convoySet.has(id));
        return {
          blockedIssue: bead.id,
          blockers,
          internalBlockers,
        };
      });

    return { hasCycles, cycleIssues, readyIssues, blockedIssues };
  }

  /**
   * Analyze dependencies with JavaScript (fallback)
   */
  private analyzeWithJS(beads: Bead[], convoyIssues: string[]): {
    hasCycles: boolean;
    cycleIssues: string[];
    readyIssues: ReadyIssueInfo[];
    blockedIssues: BlockerInfo[];
  } {
    const beadMap = new Map(beads.map(b => [b.id, b]));
    const convoySet = new Set(convoyIssues);
    const closedSet = new Set(
      beads.filter(b => b.status === 'closed').map(b => b.id)
    );

    // Simple cycle detection using DFS
    const hasCycles = this.detectCyclesJS(beads);
    const cycleIssues: string[] = hasCycles
      ? this.findCycleNodesJS(beads)
      : [];

    // Find ready issues (no unresolved blockers)
    const readyIssues: ReadyIssueInfo[] = beads
      .filter(bead => {
        if (bead.status === 'closed') return false;
        const blockers = bead.blockedBy ?? [];
        return blockers.every(id => closedSet.has(id));
      })
      .map((bead, index) => ({
        id: bead.id,
        title: bead.title,
        priority: bead.priority,
        level: 0, // Simplified - no level computation in JS fallback
      }));

    // Find blocked issues
    const blockedIssues: BlockerInfo[] = beads
      .filter(bead => {
        if (bead.status === 'closed') return false;
        const blockers = bead.blockedBy ?? [];
        return blockers.some(id => !closedSet.has(id));
      })
      .map(bead => {
        const blockers = (bead.blockedBy ?? []).filter(
          id => !closedSet.has(id)
        );
        const internalBlockers = blockers.every(id => convoySet.has(id));
        return {
          blockedIssue: bead.id,
          blockers,
          internalBlockers,
        };
      });

    return { hasCycles, cycleIssues, readyIssues, blockedIssues };
  }

  /**
   * Detect cycles using DFS (JavaScript)
   */
  private detectCyclesJS(beads: Bead[]): boolean {
    const visited = new Set<string>();
    const recStack = new Set<string>();
    const beadMap = new Map(beads.map(b => [b.id, b]));

    const dfs = (id: string): boolean => {
      visited.add(id);
      recStack.add(id);

      const bead = beadMap.get(id);
      if (bead) {
        for (const blockerId of bead.blockedBy ?? []) {
          if (!visited.has(blockerId)) {
            if (dfs(blockerId)) return true;
          } else if (recStack.has(blockerId)) {
            return true;
          }
        }
      }

      recStack.delete(id);
      return false;
    };

    for (const bead of beads) {
      if (!visited.has(bead.id)) {
        if (dfs(bead.id)) return true;
      }
    }

    return false;
  }

  /**
   * Find nodes in cycles (JavaScript)
   */
  private findCycleNodesJS(beads: Bead[]): string[] {
    // Simplified - just return all nodes that might be in cycles
    const inDegree = new Map<string, number>();
    const beadMap = new Map(beads.map(b => [b.id, b]));

    for (const bead of beads) {
      inDegree.set(bead.id, (bead.blockedBy ?? []).length);
    }

    // Remove nodes with no incoming edges iteratively
    let changed = true;
    while (changed) {
      changed = false;
      for (const [id, degree] of inDegree) {
        if (degree === 0) {
          inDegree.delete(id);
          // Decrease degree of nodes blocked by this one
          for (const bead of beads) {
            if (bead.blockedBy?.includes(id)) {
              const current = inDegree.get(bead.id) ?? 0;
              if (current > 0) {
                inDegree.set(bead.id, current - 1);
                changed = true;
              }
            }
          }
          changed = true;
        }
      }
    }

    // Remaining nodes are in cycles
    return Array.from(inDegree.keys());
  }

  /**
   * Topological sort using Kahn's algorithm (JavaScript)
   */
  private topoSortJS(beads: Bead[]): string[] {
    const beadMap = new Map(beads.map(b => [b.id, b]));
    const inDegree = new Map<string, number>();
    const result: string[] = [];

    // Initialize in-degrees
    for (const bead of beads) {
      inDegree.set(bead.id, (bead.blockedBy ?? []).length);
    }

    // Queue nodes with no dependencies
    const queue: string[] = [];
    for (const [id, degree] of inDegree) {
      if (degree === 0) {
        queue.push(id);
      }
    }

    while (queue.length > 0) {
      const id = queue.shift()!;
      result.push(id);

      // Find nodes blocked by this one and decrease their in-degree
      for (const bead of beads) {
        if (bead.blockedBy?.includes(id)) {
          const current = inDegree.get(bead.id) ?? 0;
          const newDegree = current - 1;
          inDegree.set(bead.id, newDegree);
          if (newDegree === 0) {
            queue.push(bead.id);
          }
        }
      }
    }

    // If we couldn't process all nodes, there's a cycle
    if (result.length !== beads.length) {
      throw new GasTownError(
        'Cannot compute execution order: dependency cycle detected',
        GasTownErrorCode.DEPENDENCY_CYCLE
      );
    }

    return result;
  }

  /**
   * Clean up resources
   */
  dispose(): void {
    this.stopAll();
    this.removeAllListeners();
  }
}

/**
 * Create a new convoy observer instance
 */
export function createConvoyObserver(
  config: ConvoyObserverConfig,
  logger?: ObserverLogger
): ConvoyObserver {
  return new ConvoyObserver(config, logger);
}

/**
 * Create a lazy-initialized convoy observer.
 * The observer is only created when first accessed (via watch() or checkCompletion()).
 * Useful for deferring initialization until convoy monitoring is actually needed.
 *
 * @example
 * ```typescript
 * const lazyObserver = createLazyConvoyObserver(config);
 *
 * // Observer is NOT created yet
 * console.log(lazyObserver.getWatchCount()); // 0
 *
 * // First watch triggers observer creation
 * const observer = await lazyObserver.watch();
 * const handle = observer.watch(convoyId, callback);
 *
 * // When done, unwatch to potentially dispose
 * await lazyObserver.unwatch();
 * ```
 */
export function createLazyConvoyObserver(
  config: ConvoyObserverConfig,
  logger?: ObserverLogger
): LazyObserver<ConvoyObserver> {
  return new LazyObserver<ConvoyObserver>(
    () => new ConvoyObserver(config, logger),
    {
      name: 'convoy-observer',
      cleanup: (observer) => {
        observer.dispose();
      },
    }
  );
}

/**
 * Get lazy observer statistics
 */
export function getLazyObserverStats(
  lazyObserver: LazyObserver<ConvoyObserver>
): {
  isActive: boolean;
  watchCount: number;
} {
  return {
    isActive: lazyObserver.isActive(),
    watchCount: lazyObserver.getWatchCount(),
  };
}

export default ConvoyObserver;

/**
 * Convoy Tracker
 *
 * Manages convoy lifecycle including creation, modification, progress
 * tracking, and completion. Convoys are work-order groups that track
 * related beads (issues) through their lifecycle.
 *
 * Features:
 * - Create and manage convoy groups
 * - Add/remove beads to convoys
 * - Track progress and status changes
 * - Event emission for status transitions
 * - Integration with bd-bridge for bead operations
 *
 * @module gastown-bridge/convoy/tracker
 */

import { EventEmitter } from 'events';
import { z } from 'zod';
import { v4 as uuidv4 } from 'uuid';
import type {
  Convoy,
  ConvoyStatus,
  ConvoyProgress,
  CreateConvoyOptions,
  Bead,
  BeadStatus,
} from '../types.js';
import {
  ConvoySchema,
  CreateConvoyOptionsSchema,
} from '../types.js';
import { BdBridge, type BeadQuery } from '../bridges/bd-bridge.js';
import { ConvoyError, GasTownErrorCode, wrapError } from '../errors.js';

// ============================================================================
// Types
// ============================================================================

/**
 * Convoy event types
 */
export type ConvoyEventType =
  | 'convoy:created'
  | 'convoy:started'
  | 'convoy:progressed'
  | 'convoy:completed'
  | 'convoy:cancelled'
  | 'convoy:paused'
  | 'convoy:resumed'
  | 'convoy:issue:added'
  | 'convoy:issue:removed'
  | 'convoy:issue:updated';

/**
 * Convoy event payload
 */
export interface ConvoyEvent {
  /** Event type */
  type: ConvoyEventType;
  /** Convoy ID */
  convoyId: string;
  /** Convoy name */
  convoyName: string;
  /** Event timestamp */
  timestamp: Date;
  /** Previous status (for status change events) */
  previousStatus?: ConvoyStatus;
  /** Current status */
  status: ConvoyStatus;
  /** Progress at time of event */
  progress: ConvoyProgress;
  /** Issue IDs affected (for issue events) */
  issues?: string[];
  /** Cancellation reason (for cancelled events) */
  reason?: string;
  /** Additional metadata */
  metadata?: Record<string, unknown>;
}

/**
 * Convoy tracker configuration
 */
export interface ConvoyTrackerConfig {
  /** BD bridge instance for bead operations */
  bdBridge: BdBridge;
  /** Auto-update progress on issue changes */
  autoUpdateProgress?: boolean;
  /** Progress update interval in milliseconds */
  progressUpdateInterval?: number;
  /** Enable persistent storage */
  persistConvoys?: boolean;
  /** Storage path for convoy data */
  storagePath?: string;
}

/**
 * Internal convoy storage
 */
interface ConvoyStore {
  convoy: Convoy;
  createdAt: Date;
  updatedAt: Date;
  metadata: Record<string, unknown>;
}

/**
 * Logger interface
 */
export interface ConvoyLogger {
  debug: (msg: string, meta?: Record<string, unknown>) => void;
  info: (msg: string, meta?: Record<string, unknown>) => void;
  warn: (msg: string, meta?: Record<string, unknown>) => void;
  error: (msg: string, meta?: Record<string, unknown>) => void;
}

// ============================================================================
// Default Logger
// ============================================================================

const defaultLogger: ConvoyLogger = {
  debug: (msg, meta) => console.debug(`[convoy-tracker] ${msg}`, meta ?? ''),
  info: (msg, meta) => console.info(`[convoy-tracker] ${msg}`, meta ?? ''),
  warn: (msg, meta) => console.warn(`[convoy-tracker] ${msg}`, meta ?? ''),
  error: (msg, meta) => console.error(`[convoy-tracker] ${msg}`, meta ?? ''),
};

// ============================================================================
// Validation Schemas
// ============================================================================

/**
 * Convoy ID schema
 */
const ConvoyIdSchema = z.string()
  .uuid('Invalid convoy ID format');

/**
 * Issue ID array schema
 */
const IssueIdsSchema = z.array(z.string().min(1))
  .min(1, 'At least one issue ID required');

// ============================================================================
// Convoy Tracker Implementation
// ============================================================================

/**
 * Convoy Tracker
 *
 * Manages convoy lifecycle and tracks progress of grouped work.
 *
 * @example
 * ```typescript
 * const tracker = new ConvoyTracker({
 *   bdBridge: await createBdBridge().initialize(),
 * });
 *
 * // Create a convoy
 * const convoy = await tracker.create(
 *   'Sprint 1',
 *   ['gt-abc12', 'gt-def34', 'gt-ghi56'],
 *   'First sprint tasks'
 * );
 *
 * // Monitor progress
 * tracker.on('convoy:progressed', (event) => {
 *   console.log(`Progress: ${event.progress.closed}/${event.progress.total}`);
 * });
 *
 * // Check status
 * const status = await tracker.getStatus(convoy.id);
 * ```
 */
export class ConvoyTracker extends EventEmitter {
  private bdBridge: BdBridge;
  private convoys: Map<string, ConvoyStore> = new Map();
  private logger: ConvoyLogger;
  private config: Required<Omit<ConvoyTrackerConfig, 'bdBridge'>>;
  private progressTimers: Map<string, NodeJS.Timeout> = new Map();

  constructor(config: ConvoyTrackerConfig, logger?: ConvoyLogger) {
    super();
    this.bdBridge = config.bdBridge;
    this.logger = logger ?? defaultLogger;
    this.config = {
      autoUpdateProgress: config.autoUpdateProgress ?? true,
      progressUpdateInterval: config.progressUpdateInterval ?? 30000,
      persistConvoys: config.persistConvoys ?? false,
      storagePath: config.storagePath ?? './data/convoys',
    };
  }

  /**
   * Create a new convoy
   *
   * @param name - Convoy name
   * @param issues - Issue IDs to include
   * @param description - Optional description
   * @returns Created convoy
   */
  async create(
    name: string,
    issues: string[],
    description?: string
  ): Promise<Convoy> {
    // Validate inputs
    const validatedOptions = CreateConvoyOptionsSchema.parse({
      name,
      issues,
      description,
    });

    // Verify issues exist
    const verifiedIssues = await this.verifyIssues(validatedOptions.issues);
    if (verifiedIssues.length === 0) {
      throw ConvoyError.createFailed('No valid issues found');
    }

    // Calculate initial progress
    const progress = await this.calculateProgress(verifiedIssues);

    // Create convoy
    const convoyId = uuidv4();
    const now = new Date();

    const convoy: Convoy = {
      id: convoyId,
      name: validatedOptions.name,
      trackedIssues: verifiedIssues,
      status: 'active',
      startedAt: now,
      progress,
      description: validatedOptions.description,
    };

    // Store convoy
    this.convoys.set(convoyId, {
      convoy,
      createdAt: now,
      updatedAt: now,
      metadata: {},
    });

    // Emit creation event
    this.emitConvoyEvent('convoy:created', convoy);

    // Start progress tracking if enabled
    if (this.config.autoUpdateProgress) {
      this.startProgressTracking(convoyId);
    }

    this.logger.info('Convoy created', {
      convoyId,
      name,
      issueCount: verifiedIssues.length,
    });

    return convoy;
  }

  /**
   * Add issues to an existing convoy
   *
   * @param convoyId - Convoy ID
   * @param issues - Issue IDs to add
   * @returns Updated convoy
   */
  async addIssues(convoyId: string, issues: string[]): Promise<Convoy> {
    // Validate inputs
    ConvoyIdSchema.parse(convoyId);
    IssueIdsSchema.parse(issues);

    const store = this.convoys.get(convoyId);
    if (!store) {
      throw ConvoyError.notFound(convoyId);
    }

    // Verify issues
    const verifiedIssues = await this.verifyIssues(issues);
    if (verifiedIssues.length === 0) {
      throw new ConvoyError(
        'No valid issues to add',
        GasTownErrorCode.CONVOY_CREATE_FAILED,
        { convoyId, issues }
      );
    }

    // Add new issues (avoid duplicates)
    const existingSet = new Set(store.convoy.trackedIssues);
    const newIssues = verifiedIssues.filter(id => !existingSet.has(id));

    if (newIssues.length === 0) {
      return store.convoy;
    }

    // Update convoy
    const updatedIssues = [...store.convoy.trackedIssues, ...newIssues];
    const progress = await this.calculateProgress(updatedIssues);

    const updatedConvoy: Convoy = {
      ...store.convoy,
      trackedIssues: updatedIssues,
      progress,
    };

    store.convoy = updatedConvoy;
    store.updatedAt = new Date();

    // Emit event
    this.emitConvoyEvent('convoy:issue:added', updatedConvoy, {
      issues: newIssues,
    });

    this.logger.info('Issues added to convoy', {
      convoyId,
      addedCount: newIssues.length,
      totalCount: updatedIssues.length,
    });

    return updatedConvoy;
  }

  /**
   * Remove issues from a convoy
   *
   * @param convoyId - Convoy ID
   * @param issues - Issue IDs to remove
   * @returns Updated convoy
   */
  async removeIssues(convoyId: string, issues: string[]): Promise<Convoy> {
    // Validate inputs
    ConvoyIdSchema.parse(convoyId);
    IssueIdsSchema.parse(issues);

    const store = this.convoys.get(convoyId);
    if (!store) {
      throw ConvoyError.notFound(convoyId);
    }

    // Remove issues
    const removeSet = new Set(issues);
    const remainingIssues = store.convoy.trackedIssues.filter(
      id => !removeSet.has(id)
    );

    if (remainingIssues.length === store.convoy.trackedIssues.length) {
      return store.convoy;
    }

    // Recalculate progress
    const progress = remainingIssues.length > 0
      ? await this.calculateProgress(remainingIssues)
      : { total: 0, closed: 0, inProgress: 0, blocked: 0 };

    const updatedConvoy: Convoy = {
      ...store.convoy,
      trackedIssues: remainingIssues,
      progress,
    };

    store.convoy = updatedConvoy;
    store.updatedAt = new Date();

    // Emit event
    const removedIssues = issues.filter(id =>
      store.convoy.trackedIssues.includes(id) && !remainingIssues.includes(id)
    );

    this.emitConvoyEvent('convoy:issue:removed', updatedConvoy, {
      issues: removedIssues,
    });

    this.logger.info('Issues removed from convoy', {
      convoyId,
      removedCount: removedIssues.length,
      remainingCount: remainingIssues.length,
    });

    return updatedConvoy;
  }

  /**
   * Get convoy status
   *
   * @param convoyId - Convoy ID
   * @returns Convoy with updated progress
   */
  async getStatus(convoyId: string): Promise<Convoy> {
    ConvoyIdSchema.parse(convoyId);

    const store = this.convoys.get(convoyId);
    if (!store) {
      throw ConvoyError.notFound(convoyId);
    }

    // Refresh progress
    const progress = await this.calculateProgress(store.convoy.trackedIssues);
    const previousProgress = store.convoy.progress;

    // Check if progress changed
    if (
      progress.closed !== previousProgress.closed ||
      progress.inProgress !== previousProgress.inProgress ||
      progress.blocked !== previousProgress.blocked
    ) {
      const updatedConvoy: Convoy = {
        ...store.convoy,
        progress,
      };

      store.convoy = updatedConvoy;
      store.updatedAt = new Date();

      this.emitConvoyEvent('convoy:progressed', updatedConvoy);
    }

    return store.convoy;
  }

  /**
   * Mark convoy as complete
   *
   * @param convoyId - Convoy ID
   * @returns Completed convoy
   */
  async complete(convoyId: string): Promise<Convoy> {
    ConvoyIdSchema.parse(convoyId);

    const store = this.convoys.get(convoyId);
    if (!store) {
      throw ConvoyError.notFound(convoyId);
    }

    if (store.convoy.status === 'landed') {
      return store.convoy;
    }

    const previousStatus = store.convoy.status;
    const now = new Date();

    const completedConvoy: Convoy = {
      ...store.convoy,
      status: 'landed',
      completedAt: now,
    };

    store.convoy = completedConvoy;
    store.updatedAt = now;

    // Stop progress tracking
    this.stopProgressTracking(convoyId);

    // Emit event
    this.emitConvoyEvent('convoy:completed', completedConvoy, {
      previousStatus,
    });

    this.logger.info('Convoy completed', {
      convoyId,
      name: completedConvoy.name,
      duration: now.getTime() - completedConvoy.startedAt.getTime(),
    });

    return completedConvoy;
  }

  /**
   * Cancel a convoy
   *
   * @param convoyId - Convoy ID
   * @param reason - Cancellation reason
   * @returns Cancelled convoy
   */
  async cancel(convoyId: string, reason?: string): Promise<Convoy> {
    ConvoyIdSchema.parse(convoyId);

    const store = this.convoys.get(convoyId);
    if (!store) {
      throw ConvoyError.notFound(convoyId);
    }

    if (store.convoy.status === 'failed' || store.convoy.status === 'landed') {
      return store.convoy;
    }

    const previousStatus = store.convoy.status;
    const now = new Date();

    const cancelledConvoy: Convoy = {
      ...store.convoy,
      status: 'failed',
      completedAt: now,
    };

    store.convoy = cancelledConvoy;
    store.updatedAt = now;
    store.metadata.cancellationReason = reason;

    // Stop progress tracking
    this.stopProgressTracking(convoyId);

    // Emit event
    this.emitConvoyEvent('convoy:cancelled', cancelledConvoy, {
      previousStatus,
      reason,
    });

    this.logger.info('Convoy cancelled', {
      convoyId,
      name: cancelledConvoy.name,
      reason,
    });

    return cancelledConvoy;
  }

  /**
   * Pause a convoy
   *
   * @param convoyId - Convoy ID
   * @returns Paused convoy
   */
  async pause(convoyId: string): Promise<Convoy> {
    ConvoyIdSchema.parse(convoyId);

    const store = this.convoys.get(convoyId);
    if (!store) {
      throw ConvoyError.notFound(convoyId);
    }

    if (store.convoy.status !== 'active') {
      return store.convoy;
    }

    const previousStatus = store.convoy.status;

    const pausedConvoy: Convoy = {
      ...store.convoy,
      status: 'paused',
    };

    store.convoy = pausedConvoy;
    store.updatedAt = new Date();

    // Stop progress tracking while paused
    this.stopProgressTracking(convoyId);

    // Emit event
    this.emitConvoyEvent('convoy:paused', pausedConvoy, {
      previousStatus,
    });

    this.logger.info('Convoy paused', {
      convoyId,
      name: pausedConvoy.name,
    });

    return pausedConvoy;
  }

  /**
   * Resume a paused convoy
   *
   * @param convoyId - Convoy ID
   * @returns Resumed convoy
   */
  async resume(convoyId: string): Promise<Convoy> {
    ConvoyIdSchema.parse(convoyId);

    const store = this.convoys.get(convoyId);
    if (!store) {
      throw ConvoyError.notFound(convoyId);
    }

    if (store.convoy.status !== 'paused') {
      return store.convoy;
    }

    const previousStatus = store.convoy.status;

    const resumedConvoy: Convoy = {
      ...store.convoy,
      status: 'active',
    };

    store.convoy = resumedConvoy;
    store.updatedAt = new Date();

    // Resume progress tracking
    if (this.config.autoUpdateProgress) {
      this.startProgressTracking(convoyId);
    }

    // Emit event
    this.emitConvoyEvent('convoy:resumed', resumedConvoy, {
      previousStatus,
    });

    this.logger.info('Convoy resumed', {
      convoyId,
      name: resumedConvoy.name,
    });

    return resumedConvoy;
  }

  /**
   * List all convoys
   *
   * @param status - Optional status filter
   * @returns Array of convoys
   */
  listConvoys(status?: ConvoyStatus): Convoy[] {
    const convoys = Array.from(this.convoys.values())
      .map(store => store.convoy);

    if (status) {
      return convoys.filter(convoy => convoy.status === status);
    }

    return convoys;
  }

  /**
   * Get convoy by ID
   *
   * @param convoyId - Convoy ID
   * @returns Convoy or undefined
   */
  getConvoy(convoyId: string): Convoy | undefined {
    return this.convoys.get(convoyId)?.convoy;
  }

  /**
   * Delete a convoy
   *
   * @param convoyId - Convoy ID
   * @returns True if deleted
   */
  deleteConvoy(convoyId: string): boolean {
    this.stopProgressTracking(convoyId);
    return this.convoys.delete(convoyId);
  }

  /**
   * Calculate progress for a set of issues
   */
  private async calculateProgress(issueIds: string[]): Promise<ConvoyProgress> {
    if (issueIds.length === 0) {
      return { total: 0, closed: 0, inProgress: 0, blocked: 0 };
    }

    try {
      // Fetch beads
      const beads = await this.fetchBeads(issueIds);
      const beadMap = new Map(beads.map(b => [b.id, b]));

      let closed = 0;
      let inProgress = 0;
      let blocked = 0;

      for (const issueId of issueIds) {
        const bead = beadMap.get(issueId);
        if (!bead) continue;

        if (bead.status === 'closed') {
          closed++;
        } else if (bead.status === 'in_progress') {
          inProgress++;
        }

        // Check if blocked
        if (bead.blockedBy && bead.blockedBy.length > 0) {
          const hasOpenBlocker = bead.blockedBy.some(blockerId => {
            const blocker = beadMap.get(blockerId);
            return blocker && blocker.status !== 'closed';
          });
          if (hasOpenBlocker) {
            blocked++;
          }
        }
      }

      return {
        total: issueIds.length,
        closed,
        inProgress,
        blocked,
      };
    } catch (error) {
      this.logger.warn('Failed to calculate progress', {
        issueIds,
        error: error instanceof Error ? error.message : String(error),
      });

      return {
        total: issueIds.length,
        closed: 0,
        inProgress: 0,
        blocked: 0,
      };
    }
  }

  /**
   * Verify issues exist
   */
  private async verifyIssues(issueIds: string[]): Promise<string[]> {
    const verified: string[] = [];

    for (const id of issueIds) {
      try {
        await this.bdBridge.getBead(id);
        verified.push(id);
      } catch {
        this.logger.warn('Issue not found', { issueId: id });
      }
    }

    return verified;
  }

  /**
   * Fetch beads by IDs
   */
  private async fetchBeads(issueIds: string[]): Promise<Bead[]> {
    const beads: Bead[] = [];

    for (const id of issueIds) {
      try {
        const cliBead = await this.bdBridge.getBead(id);
        // Convert CLI bead to Gas Town bead
        beads.push({
          id: cliBead.id,
          title: cliBead.content.slice(0, 100),
          description: cliBead.content,
          status: this.mapBeadStatus(cliBead.type),
          priority: 0,
          labels: cliBead.tags ?? [],
          createdAt: cliBead.timestamp ? new Date(cliBead.timestamp) : new Date(),
          updatedAt: new Date(),
          blockedBy: cliBead.parentId ? [cliBead.parentId] : [],
        });
      } catch {
        // Skip invalid beads
      }
    }

    return beads;
  }

  /**
   * Map CLI bead type to Gas Town status
   */
  private mapBeadStatus(type: string): BeadStatus {
    switch (type) {
      case 'closed':
        return 'closed';
      case 'in_progress':
      case 'response':
      case 'code':
        return 'in_progress';
      default:
        return 'open';
    }
  }

  /**
   * Start progress tracking timer
   */
  private startProgressTracking(convoyId: string): void {
    if (this.progressTimers.has(convoyId)) {
      return;
    }

    const timer = setInterval(async () => {
      try {
        await this.getStatus(convoyId);
      } catch (error) {
        this.logger.warn('Progress tracking error', {
          convoyId,
          error: error instanceof Error ? error.message : String(error),
        });
      }
    }, this.config.progressUpdateInterval);

    this.progressTimers.set(convoyId, timer);
  }

  /**
   * Stop progress tracking timer
   */
  private stopProgressTracking(convoyId: string): void {
    const timer = this.progressTimers.get(convoyId);
    if (timer) {
      clearInterval(timer);
      this.progressTimers.delete(convoyId);
    }
  }

  /**
   * Emit convoy event
   */
  private emitConvoyEvent(
    type: ConvoyEventType,
    convoy: Convoy,
    extra?: Partial<ConvoyEvent>
  ): void {
    const event: ConvoyEvent = {
      type,
      convoyId: convoy.id,
      convoyName: convoy.name,
      timestamp: new Date(),
      status: convoy.status,
      progress: convoy.progress,
      ...extra,
    };

    this.emit(type, event);
    this.emit('convoy:*', event);
  }

  /**
   * Clean up resources
   */
  dispose(): void {
    for (const [convoyId, timer] of this.progressTimers) {
      clearInterval(timer);
    }
    this.progressTimers.clear();
    this.removeAllListeners();
  }
}

/**
 * Create a new convoy tracker instance
 */
export function createConvoyTracker(
  config: ConvoyTrackerConfig,
  logger?: ConvoyLogger
): ConvoyTracker {
  return new ConvoyTracker(config, logger);
}

export default ConvoyTracker;

/**
 * Gas Town Bridge Plugin - Typed Error Classes
 *
 * Provides a hierarchy of typed error classes for the Gas Town Bridge Plugin:
 * - GasTownError: Base error class for all Gas Town errors
 * - BeadsError: Errors related to bead operations
 * - ValidationError: Input validation failures
 * - CLIExecutionError: CLI command execution failures
 *
 * All errors include:
 * - Typed error codes for programmatic handling
 * - Stack traces for debugging
 * - Contextual information about the failure
 *
 * @module gastown-bridge/errors
 * @version 0.1.0
 */

// ============================================================================
// Error Codes
// ============================================================================

/**
 * Gas Town error codes enumeration
 */
export const GasTownErrorCode = {
  // General errors
  UNKNOWN: 'GT_UNKNOWN',
  INITIALIZATION_FAILED: 'GT_INITIALIZATION_FAILED',
  NOT_INITIALIZED: 'GT_NOT_INITIALIZED',
  CONFIGURATION_ERROR: 'GT_CONFIGURATION_ERROR',

  // Validation errors
  VALIDATION_FAILED: 'GT_VALIDATION_FAILED',
  INVALID_INPUT: 'GT_INVALID_INPUT',
  INVALID_BEAD_ID: 'GT_INVALID_BEAD_ID',
  INVALID_FORMULA_NAME: 'GT_INVALID_FORMULA_NAME',
  INVALID_CONVOY_ID: 'GT_INVALID_CONVOY_ID',
  INVALID_ARGUMENTS: 'GT_INVALID_ARGUMENTS',
  COMMAND_INJECTION_DETECTED: 'GT_COMMAND_INJECTION_DETECTED',
  PATH_TRAVERSAL_DETECTED: 'GT_PATH_TRAVERSAL_DETECTED',

  // Beads errors
  BEAD_NOT_FOUND: 'GT_BEAD_NOT_FOUND',
  BEAD_CREATE_FAILED: 'GT_BEAD_CREATE_FAILED',
  BEAD_UPDATE_FAILED: 'GT_BEAD_UPDATE_FAILED',
  BEAD_DELETE_FAILED: 'GT_BEAD_DELETE_FAILED',
  BEAD_PARSE_FAILED: 'GT_BEAD_PARSE_FAILED',

  // Formula errors
  FORMULA_NOT_FOUND: 'GT_FORMULA_NOT_FOUND',
  FORMULA_PARSE_FAILED: 'GT_FORMULA_PARSE_FAILED',
  FORMULA_COOK_FAILED: 'GT_FORMULA_COOK_FAILED',
  FORMULA_INVALID_TYPE: 'GT_FORMULA_INVALID_TYPE',

  // Convoy errors
  CONVOY_NOT_FOUND: 'GT_CONVOY_NOT_FOUND',
  CONVOY_CREATE_FAILED: 'GT_CONVOY_CREATE_FAILED',

  // CLI errors
  CLI_NOT_FOUND: 'GT_CLI_NOT_FOUND',
  CLI_TIMEOUT: 'GT_CLI_TIMEOUT',
  CLI_EXECUTION_FAILED: 'GT_CLI_EXECUTION_FAILED',
  CLI_INVALID_OUTPUT: 'GT_CLI_INVALID_OUTPUT',

  // WASM errors
  WASM_NOT_AVAILABLE: 'GT_WASM_NOT_AVAILABLE',
  WASM_EXECUTION_FAILED: 'GT_WASM_EXECUTION_FAILED',

  // Sync errors
  SYNC_FAILED: 'GT_SYNC_FAILED',
  SYNC_CONFLICT: 'GT_SYNC_CONFLICT',

  // Graph errors
  DEPENDENCY_CYCLE: 'GT_DEPENDENCY_CYCLE',
  GRAPH_ERROR: 'GT_GRAPH_ERROR',
} as const;

export type GasTownErrorCodeType = (typeof GasTownErrorCode)[keyof typeof GasTownErrorCode];

// ============================================================================
// Base Error Class
// ============================================================================

/**
 * Base error class for all Gas Town Bridge errors
 *
 * @example
 * ```typescript
 * throw new GasTownError(
 *   'Failed to initialize plugin',
 *   GasTownErrorCode.INITIALIZATION_FAILED,
 *   { configPath: '/path/to/config' }
 * );
 * ```
 */
export class GasTownError extends Error {
  /** Error code for programmatic handling */
  readonly code: GasTownErrorCodeType;

  /** Timestamp when error occurred */
  readonly timestamp: Date;

  /** Additional context about the error */
  readonly context?: Record<string, unknown>;

  /** Original error if this wraps another error */
  readonly cause?: Error;

  constructor(
    message: string,
    code: GasTownErrorCodeType = GasTownErrorCode.UNKNOWN,
    context?: Record<string, unknown>,
    cause?: Error
  ) {
    super(message);
    this.name = 'GasTownError';
    this.code = code;
    this.timestamp = new Date();
    this.context = context;
    this.cause = cause;

    // Maintain proper stack trace in V8 environments
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, GasTownError);
    }
  }

  /**
   * Convert error to JSON for logging/serialization
   */
  toJSON(): Record<string, unknown> {
    return {
      name: this.name,
      message: this.message,
      code: this.code,
      timestamp: this.timestamp.toISOString(),
      context: this.context,
      cause: this.cause?.message,
      stack: this.stack,
    };
  }

  /**
   * Create a human-readable string representation
   */
  toString(): string {
    let str = `[${this.code}] ${this.message}`;
    if (this.context) {
      str += ` | Context: ${JSON.stringify(this.context)}`;
    }
    if (this.cause) {
      str += ` | Caused by: ${this.cause.message}`;
    }
    return str;
  }
}

// ============================================================================
// Beads Error Class
// ============================================================================

/**
 * Error class for bead-related operations
 *
 * @example
 * ```typescript
 * throw new BeadsError(
 *   'Bead not found',
 *   GasTownErrorCode.BEAD_NOT_FOUND,
 *   { beadId: 'gt-abc12' }
 * );
 * ```
 */
export class BeadsError extends GasTownError {
  /** Bead ID if applicable */
  readonly beadId?: string;

  /** Operation being performed */
  readonly operation?: string;

  constructor(
    message: string,
    code: GasTownErrorCodeType = GasTownErrorCode.BEAD_NOT_FOUND,
    context?: Record<string, unknown>,
    cause?: Error
  ) {
    super(message, code, context, cause);
    this.name = 'BeadsError';

    // Extract beadId from context if present
    if (context?.beadId && typeof context.beadId === 'string') {
      this.beadId = context.beadId;
    }
    if (context?.operation && typeof context.operation === 'string') {
      this.operation = context.operation;
    }

    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, BeadsError);
    }
  }

  /**
   * Create a BeadsError for a not found scenario
   */
  static notFound(beadId: string): BeadsError {
    return new BeadsError(
      `Bead not found: ${beadId}`,
